function normalizeContractorId(id) {
  if (id == null || String(id).trim() === '') return null
  return String(id)
}

function selectionIdSet(selectionIds) {
  if (selectionIds instanceof Set) {
    return new Set([...selectionIds].map(normalizeContractorId).filter(Boolean))
  }
  return new Set((selectionIds || []).map(normalizeContractorId).filter(Boolean))
}

/** グリッドセレクト候補（contractor_selections に含まれるもののみ） */
export function filterContractorsForSelect(all, selectionIds, { includeSpecial = true } = {}) {
  const ids = selectionIdSet(selectionIds)
  if (ids.size === 0) return []

  let list = all || []
  if (!includeSpecial) {
    list = list.filter(c => !c.is_special)
  }
  return list.filter(c => ids.has(normalizeContractorId(c.id)))
}

/** 表示オフだが既に選択されている contractor（hidden option 用） */
export function getHiddenSelectedContractor(all, selectionIds, currentId) {
  const id = normalizeContractorId(currentId)
  if (!id) return null

  const ids = selectionIdSet(selectionIds)
  if (ids.size === 0 || ids.has(id)) return null

  return (all || []).find(c => normalizeContractorId(c.id) === id) || null
}
