const SUPABASE_URL = (import.meta.env.VITE_SUPABASE_URL || '').replace(/\/$/, '')
const MANUALS_STORAGE_BUCKET = 'manuals'

function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function parsePageLabels(pageLabelsJson) {
  if (Array.isArray(pageLabelsJson)) return pageLabelsJson.map(String).filter(Boolean)
  if (typeof pageLabelsJson === 'string' && pageLabelsJson.trim()) {
    try {
      const parsed = JSON.parse(pageLabelsJson)
      if (Array.isArray(parsed)) return parsed.map(String).filter(Boolean)
    } catch {
      return []
    }
  }
  return []
}

function formatPageLabels(pageLabelsJson) {
  const labels = parsePageLabels(pageLabelsJson)
  if (!labels.length) return ''
  if (labels.length === 1) return labels[0]
  return `${labels[0]}–${labels[labels.length - 1]}`
}

function highlightTextHtml(text, query) {
  const source = String(text ?? '')
  const q = String(query ?? '').trim()
  if (!q) return escapeHtml(source)

  const lower = source.toLowerCase()
  const qLower = q.toLowerCase()
  let html = ''
  let i = 0

  while (i < source.length) {
    const idx = lower.indexOf(qLower, i)
    if (idx === -1) {
      html += escapeHtml(source.slice(i))
      break
    }
    html += escapeHtml(source.slice(i, idx))
    html += `<mark class="mark-search">${escapeHtml(source.slice(idx, idx + q.length))}</mark>`
    i = idx + q.length
  }

  return html
}

function divisionKey(article) {
  return `${article.edition_code || ''}::${article.division_title || ''}`
}

function chapterKey(article) {
  return `${divisionKey(article)}::${article.chapter_no || ''}::${article.chapter_title || ''}`
}

function sectionKey(article) {
  return `${chapterKey(article)}::${article.section_no || ''}::${article.section_title || ''}`
}

function splitTableRow(line) {
  if (line.includes('\t')) {
    return line.split('\t').map((cell) => cell.trim())
  }
  if (line.includes('|')) {
    return line.split('|').map((cell) => cell.trim())
  }
  return [line.trim()]
}

function renderTableCellContent(text, highlightQuery = '') {
  if (highlightQuery) return highlightTextHtml(text, highlightQuery)
  return escapeHtml(String(text ?? '')).replace(/\n/g, '<br>')
}

function parseMetadataRows(metadataJson) {
  if (!metadataJson) return null
  let parsed = metadataJson
  if (typeof metadataJson === 'string') {
    try {
      parsed = JSON.parse(metadataJson)
    } catch {
      return null
    }
  }
  if (!Array.isArray(parsed?.rows) || !parsed.rows.length) return null
  return parsed.rows.map((row) => (Array.isArray(row) ? row : []).map((cell) => String(cell ?? '')))
}

function parseTableRowsFromTsv(displayText) {
  const lines = String(displayText ?? '')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
  if (!lines.length) return []
  return lines.map(splitTableRow)
}

function renderTableHtml(block, caption, highlightQuery = '') {
  const rows = parseMetadataRows(block.metadata_json) ?? parseTableRowsFromTsv(block.display_text || block.text)
  if (!rows.length) {
    return `<div class="doc-table-empty">${highlightTextHtml(block.display_text || block.text || caption || '', highlightQuery)}</div>`
  }

  const colCount = Math.max(...rows.map((row) => row.length))
  const normalizedRows = rows.map((row) => {
    const cells = [...row]
    while (cells.length < colCount) cells.push('')
    return cells
  })

  let html = caption ? `<div class="doc-table-caption">${highlightTextHtml(caption, highlightQuery)}</div>` : ''
  html += '<div class="doc-table-wrap"><table class="doc-table"><tbody>'
  for (let rowIndex = 0; rowIndex < normalizedRows.length; rowIndex++) {
    const tag = rowIndex === 0 ? 'th' : 'td'
    html += '<tr>'
    for (const cell of normalizedRows[rowIndex]) {
      const cellHtml = highlightQuery
        ? highlightTextHtml(cell, highlightQuery).replace(/\n/g, '<br>')
        : renderTableCellContent(cell)
      html += `<${tag}>${cellHtml}</${tag}>`
    }
    html += '</tr>'
  }
  html += '</tbody></table></div>'
  return html
}

function resolveAssetUrl(assetPath, documentCode) {
  const raw = String(assetPath ?? '').trim()
  if (!raw) return ''
  if (/^https?:\/\//i.test(raw)) return raw

  const code = String(documentCode ?? '').trim()

  if (raw.startsWith('/storage/v1/object/public/')) {
    return SUPABASE_URL ? `${SUPABASE_URL}${raw}` : raw
  }

  if (raw.startsWith('/')) {
    if (SUPABASE_URL && code && raw.startsWith(`/manual/${code}/`)) {
      const storagePath = raw.slice(`/manual/${code}/`.length)
      return `${SUPABASE_URL}/storage/v1/object/public/${MANUALS_STORAGE_BUCKET}/${code}/${storagePath}`
    }
    return raw
  }

  if (!SUPABASE_URL || !code) return raw

  const normalized = raw.replace(/^\/+/, '')
  const pathInBucket = normalized.startsWith(`${code}/`) ? normalized : `${code}/${normalized}`
  return `${SUPABASE_URL}/storage/v1/object/public/${MANUALS_STORAGE_BUCKET}/${pathInBucket}`
}

function resolveTableLabel(block) {
  const caption = String(block.caption ?? '').trim()
  if (caption) return caption
  const objectCode = String(block.object_code ?? '').trim()
  const tableIdx = objectCode.indexOf('-TABLE')
  if (tableIdx > 0) return objectCode.slice(0, tableIdx)
  return objectCode
}

function renderFigureImageHtml(block, documentCode, { altFallback = '', extraClass = '', labelHtml = '' } = {}) {
  const imgSrc = resolveAssetUrl(block.asset_path, documentCode)
  if (!imgSrc) return ''
  const alt = block.caption || altFallback || '図'
  const cls = ['doc-figure', extraClass].filter(Boolean).join(' ')
  return `<figure class="${cls}">${labelHtml}<img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(alt)}" loading="lazy" /></figure>`
}

function renderTableImageHtml(block, documentCode, highlightQuery = '') {
  const label = resolveTableLabel(block)
  const content = String(block.display_text || block.text || '')
  const alt = label || content || '表'
  const labelHtml = label
    ? `<div class="doc-table-label">${highlightTextHtml(label, highlightQuery)}</div>`
    : ''
  const imgSrc = resolveAssetUrl(block.asset_path, documentCode)
  if (imgSrc) {
    return renderFigureImageHtml(block, documentCode, {
      altFallback: alt,
      extraClass: 'doc-figure--table',
      labelHtml,
    })
  }
  return `<figure class="doc-figure doc-figure--table">${labelHtml}<div class="doc-figure--placeholder">${highlightTextHtml(alt, highlightQuery)}</div></figure>`
}

function renderBlockHtml(block, highlightBlockId, documentCode, highlightQuery = '') {
  const cls = block.block_id === highlightBlockId ? 'doc-block highlight-target' : 'doc-block'
  const content = String(block.display_text || block.text || '')
  const parts = [`<div class="${cls}" data-block-id="${escapeHtml(block.block_id)}" id="block-${escapeHtml(block.block_id)}">`]

  if (block.block_type === 'heading') {
    parts.push(`<h5 class="doc-heading">${highlightTextHtml(content, highlightQuery)}</h5>`)
  } else if (block.block_type === 'table') {
    parts.push(renderTableImageHtml(block, documentCode, highlightQuery))
  } else if (block.block_type === 'figure') {
    const figureHtml = renderFigureImageHtml(block, documentCode, { altFallback: content })
    if (figureHtml) {
      parts.push(figureHtml)
    } else {
      parts.push(`<figure class="doc-figure doc-figure--placeholder">${highlightTextHtml(block.caption || content || '図', highlightQuery)}</figure>`)
    }
  } else {
    parts.push(`<p class="doc-paragraph">${highlightTextHtml(content, highlightQuery)}</p>`)
  }

  parts.push('</div>')
  return parts.join('')
}

function renderArticleInner(article, blocks, highlightBlockId, documentCode, highlightQuery = '') {
  const parts = []
  parts.push(`<article class="doc-article" id="article-${escapeHtml(article.article_id)}" data-article-id="${escapeHtml(article.article_id)}">`)
  parts.push('<header class="doc-article-header">')
  parts.push(`<h4 class="doc-article-label">${highlightTextHtml(article.article_label || article.article_code || '', highlightQuery)}</h4>`)
  const pageLabelText = formatPageLabels(article.page_labels_json)
  if (pageLabelText) {
    parts.push(`<div class="doc-article-page">${escapeHtml(pageLabelText)}</div>`)
  }
  parts.push('</header>')
  for (const block of blocks) {
    parts.push(renderBlockHtml(block, highlightBlockId, documentCode, highlightQuery))
  }
  parts.push('</article>')
  return parts.join('\n')
}

/**
 * 文書全体を 編 → 章 → 節 → 条 の階層 HTML に組み立てる
 */
export function renderDocumentHtml(document, articles, blocksByArticleId, { highlightBlockId = '', highlightQuery = '' } = {}) {
  if (!document || !articles?.length) return ''

  const parts = []
  parts.push('<div class="doc-document">')
  parts.push('<header class="doc-document-header">')
  parts.push(`<h1 class="doc-document-title">${escapeHtml(document.title || document.document_code)}</h1>`)
  parts.push(`<p class="doc-document-meta">${escapeHtml(document.document_code)} · ${articles.length} 条</p>`)
  parts.push('</header>')

  let currentDivision = ''
  let currentChapter = ''
  let currentSection = ''

  for (const article of articles) {
    const dKey = divisionKey(article)
    const cKey = chapterKey(article)
    const sKey = sectionKey(article)

    if (dKey !== currentDivision) {
      if (currentSection) parts.push('</section>')
      if (currentChapter) parts.push('</section>')
      if (currentDivision) parts.push('</section>')
      currentDivision = dKey
      currentChapter = ''
      currentSection = ''
      const divisionSlug = escapeHtml(article.edition_code || article.division_title || 'division')
      parts.push(`<section class="doc-division" id="division-${divisionSlug}">`)
      parts.push('<div class="doc-division-head">')
      parts.push(`<span class="doc-division-badge">編</span>`)
      parts.push(`<h2 class="doc-division-title">${escapeHtml(article.division_title || article.edition_code || '')}</h2>`)
      parts.push('</div>')
    }

    if (cKey !== currentChapter) {
      if (currentSection) {
        parts.push('</section>')
        currentSection = ''
      }
      if (currentChapter) parts.push('</section>')
      currentChapter = cKey
      const chapterSlug = `${article.edition_code || 'e'}-${article.chapter_no || '0'}`
      parts.push(`<section class="doc-chapter" id="chapter-${escapeHtml(chapterSlug)}">`)
      parts.push('<div class="doc-chapter-head">')
      parts.push(`<span class="doc-chapter-badge">第${escapeHtml(article.chapter_no || '')}章</span>`)
      parts.push(`<h3 class="doc-chapter-title">${escapeHtml(article.chapter_title || '')}</h3>`)
      parts.push('</div>')
    }

    if (sKey !== currentSection) {
      if (currentSection) parts.push('</section>')
      currentSection = sKey
      const sectionSlug = `${article.edition_code || 'e'}-${article.chapter_no || '0'}-${article.section_no || '0'}`
      parts.push(`<section class="doc-section" id="section-${escapeHtml(sectionSlug)}">`)
      parts.push('<div class="doc-section-head">')
      parts.push(`<span class="doc-section-badge">第${escapeHtml(article.section_no || '')}節</span>`)
      parts.push(`<h4 class="doc-section-title">${escapeHtml(article.section_title || '')}</h4>`)
      parts.push('</div>')
    }

    const articleBlocks = blocksByArticleId.get(article.article_id) || []
    parts.push(renderArticleInner(article, articleBlocks, highlightBlockId, document.document_code, highlightQuery))
  }

  if (currentSection) parts.push('</section>')
  if (currentChapter) parts.push('</section>')
  if (currentDivision) parts.push('</section>')
  parts.push('</div>')
  return parts.join('\n')
}

export function groupBlocksByArticleId(blocks) {
  const map = new Map()
  for (const block of blocks ?? []) {
    const list = map.get(block.article_id) || []
    list.push(block)
    map.set(block.article_id, list)
  }
  for (const list of map.values()) {
    list.sort((a, b) => (a.block_no || 0) - (b.block_no || 0))
  }
  return map
}

function divisionSlug(article) {
  return String(article.edition_code || article.division_title || 'division')
}

function chapterSlug(article) {
  return `${article.edition_code || 'e'}-${article.chapter_no || '0'}`
}

function sectionSlug(article) {
  return `${article.edition_code || 'e'}-${article.chapter_no || '0'}-${article.section_no || '0'}`
}

export function buildDocumentTocTree(articles) {
  const divisions = []
  const divMap = new Map()
  const chapMap = new Map()
  const secMap = new Map()

  for (const article of articles ?? []) {
    const dKey = divisionKey(article)
    let div = divMap.get(dKey)
    if (!div) {
      div = {
        key: dKey,
        anchorId: `division-${divisionSlug(article)}`,
        label: article.division_title || article.edition_code || '',
        chapters: [],
      }
      divMap.set(dKey, div)
      divisions.push(div)
    }

    const cKey = chapterKey(article)
    const chapComposite = `${dKey}::${cKey}`
    let chap = chapMap.get(chapComposite)
    if (!chap) {
      chap = {
        key: cKey,
        anchorId: `chapter-${chapterSlug(article)}`,
        label: `第${article.chapter_no || ''}章 ${article.chapter_title || ''}`.trim(),
        sections: [],
      }
      chapMap.set(chapComposite, chap)
      div.chapters.push(chap)
    }

    const sKey = sectionKey(article)
    const secComposite = `${chapComposite}::${sKey}`
    let sec = secMap.get(secComposite)
    if (!sec) {
      sec = {
        key: sKey,
        anchorId: `section-${sectionSlug(article)}`,
        label: `第${article.section_no || ''}節 ${article.section_title || ''}`.trim(),
        articles: [],
      }
      secMap.set(secComposite, sec)
      chap.sections.push(sec)
    }

    sec.articles.push({
      articleId: article.article_id,
      anchorId: `article-${article.article_id}`,
      label: article.article_label || article.article_code || '',
    })
  }

  return divisions
}

export { formatPageLabels }

/** @deprecated renderDocumentHtml を使用 */
export function renderArticleHtml(article, blocks, options = {}) {
  return renderArticleInner(
    article,
    blocks,
    options.highlightBlockId || '',
    options.documentCode || '',
    options.highlightQuery || '',
  )
}

export function buildArticleBreadcrumb(article) {
  if (!article) return ''
  const parts = []
  if (article.division_title) parts.push(article.division_title)
  if (article.chapter_title) parts.push(`第${article.chapter_no}章 ${article.chapter_title}`)
  if (article.section_title) parts.push(`第${article.section_no}節 ${article.section_title}`)
  if (article.article_label) parts.push(article.article_label)
  return parts.join(' › ')
}
