<template>
  <div class="manual-search-tab">
    <div class="manual-search-left">
      <div class="manual-search-toolbar">
        <label class="manual-search-latest" :class="{ disabled: !isSearchAll }">
          <input v-model="latestOnly" type="checkbox" :disabled="!isSearchAll" />
          最新のみ
        </label>
        <select v-model="scopeDocumentCode" class="manual-search-select" @change="onScopeChange">
          <option :value="ALL_DOCUMENTS">すべての文書</option>
          <option v-for="doc in documents" :key="doc.document_code" :value="doc.document_code">
            {{ doc.title }}
          </option>
        </select>
      </div>

      <div class="manual-search-mode-tabs">
        <button type="button" class="mode-tab" :class="{ active: leftPanelMode === 'exact' }" @click="leftPanelMode = 'exact'">
          一致
        </button>
        <button type="button" class="mode-tab" :class="{ active: leftPanelMode === 'similar' }" @click="leftPanelMode = 'similar'">
          類似
        </button>
        <button type="button" class="mode-tab" :class="{ active: leftPanelMode === 'toc' }" @click="leftPanelMode = 'toc'">
          目次
        </button>
      </div>

      <div v-show="leftPanelMode === 'exact'" class="manual-search-form">
        <div class="search-input-row">
          <input
            v-model="exactQuery"
            type="text"
            class="search-input"
            placeholder="キーワード検索"
            @keydown.enter="runExactSearch"
          />
          <button type="button" class="search-btn" :disabled="exactLoading" @click="runExactSearch" title="検索">
            <SearchIcon :size="18" />
          </button>
        </div>
      </div>

      <div v-show="leftPanelMode === 'similar'" class="manual-search-form">
        <div class="search-input-row search-input-row--textarea">
          <textarea v-model="similarQuery" class="search-textarea" rows="3" placeholder="意味検索（長文可）" />
          <button type="button" class="search-btn" :disabled="similarLoading" @click="runSimilarSearch" title="検索">
            <SearchIcon :size="18" />
          </button>
        </div>
        <p v-if="embeddingPreloading" class="embedding-hint">類似検索モデルを読込中…</p>
      </div>

      <div ref="tocScrollRef" class="manual-search-results">
        <template v-if="leftPanelMode === 'exact'">
          <p v-if="exactLoading" class="results-status">検索中…</p>
          <p v-else-if="exactSearched && activeResults.length === 0" class="results-status">該当なし</p>
          <button
            v-for="item in activeResults"
            :key="item.block_id"
            type="button"
            class="result-item"
            :class="{ selected: isSameResult(selectedResult, item) }"
            @click="selectResult(item)"
          >
            <div v-if="isSearchAll" class="result-manual">{{ item.document_title }}</div>
            <div class="result-meta">
              <span v-if="item.division_title" class="result-division">{{ item.division_title }}</span>
              <span v-if="item.chapter_title" class="result-chapter">{{ item.chapter_title }}</span>
              <span v-if="item.section_title" class="result-section">{{ item.section_title }}</span>
              <span v-if="item.article_label" class="result-label">{{ item.article_label }}</span>
            </div>
            <div
              class="result-snippet"
              v-html="buildSnippetHtml(item.text || item.display_text, exactSearched ? lastExactSearchQuery : exactQuery)"
            />
          </button>
        </template>
        <template v-else-if="leftPanelMode === 'similar'">
          <p v-if="similarLoading" class="results-status">検索中…</p>
          <p v-else-if="similarSearched && activeResults.length === 0" class="results-status">該当なし</p>
          <button
            v-for="item in activeResults"
            :key="item.block_id"
            type="button"
            class="result-item"
            :class="{ selected: isSameResult(selectedResult, item) }"
            @click="selectResult(item)"
          >
            <div v-if="isSearchAll" class="result-manual">{{ item.document_title }}</div>
            <div class="result-meta">
              <span v-if="item.division_title" class="result-division">{{ item.division_title }}</span>
              <span v-if="item.chapter_title" class="result-chapter">{{ item.chapter_title }}</span>
              <span v-if="item.section_title" class="result-section">{{ item.section_title }}</span>
              <span v-if="item.article_label" class="result-label">{{ item.article_label }}</span>
              <span v-if="item.similarity != null" class="result-score">{{ formatSimilarity(item.similarity) }}</span>
            </div>
            <div class="result-snippet">{{ buildSnippetPlain(item.text || item.display_text, 60) }}</div>
          </button>
        </template>
        <template v-else>
          <p v-if="documentLoading" class="results-status">目次を読込中…</p>
          <p v-else-if="!documentCache?.articles?.length" class="results-status">
            {{ isSearchAll ? '目次は文書を個別に選択すると表示されます' : '文書を選択すると目次が表示されます' }}
          </p>
          <nav v-else class="toc-tree" aria-label="文書目次">
            <div
              v-for="division in tocTree"
              :key="division.key"
              class="toc-division"
            >
              <button type="button" class="toc-division-head" @click="onDivisionClick(division, $event)">
                <span class="toc-indent">{{ tocIndent(0) }}</span>{{ division.label }}
              </button>
              <details
                v-for="chapter in division.chapters"
                :key="chapterCompositeKey(division, chapter)"
                class="toc-chapter"
                :open="openChapterKey === chapterCompositeKey(division, chapter)"
              >
                <summary class="toc-summary toc-summary--chapter" @click.prevent="onChapterClick(division, chapter, $event)">
                  <span class="toc-indent">{{ tocIndent(1) }}</span>{{ chapter.label }}
                </summary>
                <details
                  v-for="section in chapter.sections"
                  :key="sectionCompositeKey(division, chapter, section)"
                  class="toc-section"
                  :open="openSectionKey === sectionCompositeKey(division, chapter, section)"
                >
                  <summary class="toc-summary toc-summary--section" @click.prevent="onSectionClick(division, chapter, section, $event)">
                    <span class="toc-indent">{{ tocIndent(2) }}</span>{{ section.label }}
                  </summary>
                  <ul class="toc-articles">
                    <li v-for="article in section.articles" :key="article.articleId">
                      <button
                        type="button"
                        class="toc-article"
                        :class="{ selected: selectedArticleId === article.articleId }"
                        @click="onArticleClick(division, chapter, section, article.articleId, $event)"
                      >
                        <span class="toc-article-label"><span class="toc-indent">{{ tocIndent(3) }}</span>{{ article.label }}</span>
                      </button>
                    </li>
                  </ul>
                </details>
              </details>
            </div>
          </nav>
        </template>
      </div>
    </div>

    <div class="manual-search-right">
      <div ref="htmlViewportRef" class="html-viewport">
        <p v-if="documentLoading" class="viewer-status">文書を読込中…</p>
        <p v-else-if="documentError" class="viewer-status viewer-status--error">{{ documentError }}</p>
        <div v-else-if="documentHtml" class="html-content-shell" v-html="documentHtml" />
        <p v-else class="viewer-status">文書を選ぶか、検索結果・目次から条を開いてください</p>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, nextTick } from 'vue'
import { supabaseService } from '../services/supabase'
import { extractManualQueryEmbeddingFloat32, preloadManualQueryEmbeddingModel } from '../utils/textEmbedding'
import { groupBlocksByArticleId, renderDocumentHtml, buildDocumentTocTree } from '../utils/documentHtml'
import SearchIcon from './icons/SearchIcon.vue'

const ALL_DOCUMENTS = '__all__'
const SNIPPET_LEN = 60

const props = defineProps({
  isActive: { type: Boolean, default: false },
})

const documents = ref([])
const scopeDocumentCode = ref('')
const latestOnly = ref(true)
const leftPanelMode = ref('exact')

const exactQuery = ref('')
const similarQuery = ref('')
const exactResults = ref([])
const similarResults = ref([])
const exactSearched = ref(false)
const similarSearched = ref(false)
const exactLoading = ref(false)
const similarLoading = ref(false)
const embeddingPreloading = ref(false)
const lastExactSearchQuery = ref('')

const selectedResult = ref(null)
const selectedArticleId = ref('')
const viewerDocumentCode = ref('')
const highlightBlockId = ref('')

const documentLoading = ref(false)
const documentError = ref('')
const documentHtml = ref('')
const htmlViewportRef = ref(null)
const tocScrollRef = ref(null)
const documentCache = ref(null)
const openChapterKey = ref('')
const openSectionKey = ref('')

const isSearchAll = computed(() => !scopeDocumentCode.value || scopeDocumentCode.value === ALL_DOCUMENTS)
const activeResults = computed(() => (leftPanelMode.value === 'exact' ? exactResults.value : similarResults.value))
const tocTree = computed(() => buildDocumentTocTree(documentCache.value?.articles ?? []))

function isSameResult(a, b) {
  return a && b && a.block_id === b.block_id
}

function formatSimilarity(sim) {
  const n = Number(sim)
  if (!Number.isFinite(n)) return ''
  return `${(n * 100).toFixed(1)}%`
}

function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

function buildSnippetPlain(text, maxLen = SNIPPET_LEN) {
  const normalized = String(text ?? '').replace(/\s+/g, ' ').trim()
  if (normalized.length <= maxLen) return normalized
  return `${normalized.slice(0, maxLen)}…`
}

function buildSnippetHtml(text, query, maxLen = SNIPPET_LEN) {
  const normalized = String(text ?? '').replace(/\s+/g, ' ').trim()
  const q = String(query ?? '').trim()
  let snippet = normalized
  let highlightStart = -1

  if (q) {
    const idx = normalized.toLowerCase().indexOf(q.toLowerCase())
    if (idx >= 0) {
      const pad = Math.max(0, Math.floor((maxLen - q.length) / 2))
      const start = Math.max(0, idx - pad)
      const end = Math.min(normalized.length, start + maxLen)
      snippet = normalized.slice(start, end)
      if (start > 0) snippet = `…${snippet}`
      if (end < normalized.length) snippet = `${snippet}…`
      highlightStart = idx - start + (start > 0 ? 1 : 0)
    } else {
      snippet = buildSnippetPlain(normalized, maxLen)
    }
  } else {
    snippet = buildSnippetPlain(normalized, maxLen)
  }

  const escaped = escapeHtml(snippet)
  if (q && highlightStart >= 0) {
    const hs = highlightStart
    const he = hs + q.length
    if (he <= snippet.length) {
      return (
        escapeHtml(snippet.slice(0, hs))
        + `<mark class="mark-search">${escapeHtml(snippet.slice(hs, he))}</mark>`
        + escapeHtml(snippet.slice(he))
      )
    }
  }
  return escaped
}

function buildSearchParams() {
  if (scopeDocumentCode.value && scopeDocumentCode.value !== ALL_DOCUMENTS) {
    return { document_code: scopeDocumentCode.value }
  }
  const params = { search_all: true }
  if (latestOnly.value) params.latest_only = true
  return params
}

function resolveDefaultDocumentCode() {
  const def = documents.value.find((d) => d.is_default)
  if (def) return def.document_code
  return documents.value[0]?.document_code ?? ''
}

async function loadDocuments() {
  const res = await supabaseService.listDocuments()
  if (res?.error) throw new Error(res.error)
  documents.value = res.documents ?? []
  if (!scopeDocumentCode.value) {
    scopeDocumentCode.value = resolveDefaultDocumentCode()
  }
  if (scopeDocumentCode.value && scopeDocumentCode.value !== ALL_DOCUMENTS) {
    await loadDocumentContent(scopeDocumentCode.value)
  }
}

function tocIndent(level) {
  return ' '.repeat(Math.max(0, level))
}

function chapterCompositeKey(division, chapter) {
  return `${division.key}::${chapter.key}`
}

function sectionCompositeKey(division, chapter, section) {
  return `${chapterCompositeKey(division, chapter)}::${section.key}`
}

function resetTocExpansion() {
  openChapterKey.value = ''
  openSectionKey.value = ''
}

function setTocExpansion({ chapterKey = '', sectionKey = '' } = {}) {
  openChapterKey.value = chapterKey
  openSectionKey.value = sectionKey
}

async function withTocScrollPreserved(anchorEl, updateFn) {
  const container = tocScrollRef.value
  let relativeY = null
  if (container && anchorEl instanceof Element) {
    relativeY = anchorEl.getBoundingClientRect().top - container.getBoundingClientRect().top
  }

  updateFn()
  await nextTick()

  if (container && anchorEl instanceof Element && relativeY != null) {
    await new Promise((resolve) => {
      requestAnimationFrame(() => {
        const newRelativeY = anchorEl.getBoundingClientRect().top - container.getBoundingClientRect().top
        container.scrollTop += newRelativeY - relativeY
        resolve()
      })
    })
  }
}

async function onDivisionClick(division, event) {
  await withTocScrollPreserved(event?.currentTarget, () => {
    resetTocExpansion()
  })
  await scrollToAnchor(division.anchorId)
}

async function onChapterClick(division, chapter, event) {
  const chapterKey = chapterCompositeKey(division, chapter)
  await withTocScrollPreserved(event?.currentTarget, () => {
    if (openChapterKey.value === chapterKey) {
      setTocExpansion()
    } else {
      setTocExpansion({ chapterKey })
    }
  })
}

async function onSectionClick(division, chapter, section, event) {
  const chapterKey = chapterCompositeKey(division, chapter)
  const sectionKey = sectionCompositeKey(division, chapter, section)
  await withTocScrollPreserved(event?.currentTarget, () => {
    if (openSectionKey.value === sectionKey) {
      setTocExpansion({ chapterKey })
    } else {
      setTocExpansion({ chapterKey, sectionKey })
    }
  })
}

async function onArticleClick(division, chapter, section, articleId, event) {
  await withTocScrollPreserved(event?.currentTarget, () => {
    setTocExpansion({
      chapterKey: chapterCompositeKey(division, chapter),
      sectionKey: sectionCompositeKey(division, chapter, section),
    })
  })
  await scrollToArticle(articleId)
}

function resolveHighlightQuery() {
  if (leftPanelMode.value !== 'exact') return ''
  return lastExactSearchQuery.value.trim()
}

function applyDocumentHtml(highlightId = '') {
  if (!documentCache.value) {
    documentHtml.value = ''
    return
  }
  documentHtml.value = renderDocumentHtml(
    documentCache.value.document,
    documentCache.value.articles,
    documentCache.value.blocksByArticle,
    { highlightBlockId: highlightId, highlightQuery: resolveHighlightQuery() },
  )
}

async function loadDocumentContent(documentCode, { scrollToBlockId = '' } = {}) {
  if (!documentCode) {
    documentCache.value = null
    documentHtml.value = ''
    resetTocExpansion()
    return
  }

  viewerDocumentCode.value = documentCode
  highlightBlockId.value = scrollToBlockId || ''
  documentLoading.value = true
  documentError.value = ''
  resetTocExpansion()

  try {
    const res = await supabaseService.getDocumentContent({ document_code: documentCode })
    if (res?.error) throw new Error(res.error)
    documentCache.value = {
      document: res.document,
      articles: res.articles ?? [],
      blocksByArticle: groupBlocksByArticleId(res.blocks),
    }
    applyDocumentHtml(scrollToBlockId)
    if (scrollToBlockId) {
      await scrollToBlock(scrollToBlockId)
    }
  } catch (e) {
    console.error(e)
    documentError.value = '文書の読込に失敗しました'
    documentCache.value = null
    documentHtml.value = ''
  } finally {
    documentLoading.value = false
  }
}

async function scrollToAnchor(anchorId) {
  if (!anchorId) return
  await nextTick()
  const root = htmlViewportRef.value
  if (!root) return

  root.querySelectorAll('.highlight-target, .toc-highlight').forEach((el) => {
    el.classList.remove('highlight-target', 'toc-highlight')
  })

  const el = root.querySelector(`#${CSS.escape(anchorId)}`)
  if (!el) return
  el.classList.add('toc-highlight')
  el.scrollIntoView({ behavior: 'auto', block: 'start' })
}

async function scrollToArticle(articleId) {
  if (!articleId) return
  selectedArticleId.value = articleId
  selectedResult.value = null
  highlightBlockId.value = ''
  applyDocumentHtml('')
  await scrollToAnchor(`article-${articleId}`)
}

async function scrollToBlock(blockId) {
  if (!blockId) return
  highlightBlockId.value = blockId
  selectedArticleId.value = ''
  applyDocumentHtml(blockId)
  await nextTick()
  const root = htmlViewportRef.value
  if (!root) return

  root.querySelectorAll('.highlight-target, .toc-highlight').forEach((el) => {
    el.classList.remove('highlight-target', 'toc-highlight')
  })

  const blockEl = root.querySelector(`#block-${CSS.escape(blockId)}`)
  if (!blockEl) return
  blockEl.classList.add('highlight-target')
  blockEl.scrollIntoView({ behavior: 'auto', block: 'center' })
}

async function selectResult(result) {
  selectedResult.value = result
  selectedArticleId.value = ''

  if (result.document_code !== viewerDocumentCode.value) {
    scopeDocumentCode.value = result.document_code
    await loadDocumentContent(result.document_code, { scrollToBlockId: result.block_id })
    return
  }

  if (!documentCache.value) {
    await loadDocumentContent(result.document_code, { scrollToBlockId: result.block_id })
    return
  }

  applyDocumentHtml(result.block_id)
  await scrollToBlock(result.block_id)
}

function onScopeChange() {
  selectedResult.value = null
  selectedArticleId.value = ''
  highlightBlockId.value = ''
  if (scopeDocumentCode.value && scopeDocumentCode.value !== ALL_DOCUMENTS) {
    loadDocumentContent(scopeDocumentCode.value)
  } else {
    documentCache.value = null
    documentHtml.value = ''
    documentError.value = ''
    resetTocExpansion()
  }
}

async function runExactSearch() {
  const query = exactQuery.value.trim()
  if (!query) return
  exactLoading.value = true
  exactSearched.value = false
  try {
    const res = await supabaseService.searchDocumentByText({ query, limit: 20, ...buildSearchParams() })
    if (res?.error) throw new Error(res.error)
    lastExactSearchQuery.value = query
    exactResults.value = res.results ?? []
    exactSearched.value = true
    if (documentCache.value) {
      applyDocumentHtml(highlightBlockId.value)
    }
  } catch (e) {
    console.error(e)
    exactResults.value = []
    exactSearched.value = true
  } finally {
    exactLoading.value = false
  }
}

async function runSimilarSearch() {
  const query = similarQuery.value.trim()
  if (!query) return
  similarLoading.value = true
  similarSearched.value = false
  try {
    const embedding = Array.from(await extractManualQueryEmbeddingFloat32(query))
    const res = await supabaseService.searchDocumentByEmbedding({
      embedding,
      limit: 20,
      ...buildSearchParams(),
    })
    if (res?.error) throw new Error(res.error)
    similarResults.value = res.results ?? []
    similarSearched.value = true
  } catch (e) {
    console.error(e)
    similarResults.value = []
    similarSearched.value = true
  } finally {
    similarLoading.value = false
  }
}

watch(
  () => leftPanelMode.value,
  () => {
    if (documentCache.value) {
      applyDocumentHtml(highlightBlockId.value)
    }
  },
)

watch(
  () => props.isActive,
  (active) => {
    if (!active) return
    if (!documents.value.length) {
      loadDocuments().catch(console.error)
    }
    if (!embeddingPreloading.value) {
      embeddingPreloading.value = true
      preloadManualQueryEmbeddingModel().finally(() => {
        embeddingPreloading.value = false
      })
    }
  },
  { immediate: true },
)

defineExpose({
  reloadDocuments: loadDocuments,
})
</script>

<style scoped>
