.manual-search-mode-tabs { display: flex; border-bottom: 1px solid #e5e7eb; }
.mode-tab { flex: 1; padding: 0.5rem; border: none; background: #f3f4f6; cursor: pointer; font-size: 1rem; }
.mode-tab.active { background: #fff; font-weight: 600; box-shadow: inset 0 -2px 0 #3b82f6; }

.manual-search-form { padding: 0.75rem; border-bottom: 1px solid #e5e7eb; }
.search-input-row { display: flex; gap: 0.5rem; align-items: center; }
.search-input-row--textarea { align-items: flex-start; }
.search-input, .search-textarea {
  flex: 1; min-width: 0; border: 1px solid #d1d5db; border-radius: 0.375rem; padding: 0.5rem; font-size: 1rem;
}
.search-textarea { resize: vertical; min-height: 4.5rem; }
.search-btn {
  flex-shrink: 0; width: 2.5rem; height: 2.5rem; border: 1px solid #d1d5db; border-radius: 0.375rem;
  background: #fff; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #374151;
}
.search-btn:disabled { opacity: 0.5; cursor: not-allowed; }
.embedding-hint { margin: 0.5rem 0 0; font-size: 0.875rem; color: #6b7280; }

.toc-tree { padding: 0.5rem 0.625rem 1rem; font-size: 0.9375rem; }
.toc-tree details { margin: 0.15rem 0; }
.toc-division { margin-bottom: 0.35rem; }
.toc-division-head {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.35rem 0.25rem;
  margin: 0 0 0.15rem;
  border: none;
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  font-weight: 700;
  color: #ea580c;
  font-size: inherit;
  font-family: inherit;
}
.toc-division-head:hover { color: #c2410c; text-decoration: underline; }
.toc-indent { white-space: pre; }
