.toc-summary--chapter:hover { color: #15803d; text-decoration: underline; }
.toc-summary--section { font-weight: 600; color: #2563eb; font-size: 0.9rem; }
.toc-summary--section:hover { color: #1d4ed8; text-decoration: underline; }
