.toc-article.selected { background: #f3f4f6; box-shadow: inset 0 0 0 1px #d1d5db; }
.toc-article-label { font-size: 0.9375rem; line-height: 1.4; color: #111827; }

.manual-search-results { flex: 1; overflow-y: auto; min-height: 0; }
