<template>
  <div v-if="show" class="user-item-modal-overlay">
    <div class="user-item-modal" @click.stop>
      <div class="user-item-modal-body">
        <!-- 左: 見積グリッド PC 版プライスリストと同型（ラージ単価） -->
        <div
          class="user-item-modal-left user-item-modal-price-panel"
          :class="{ 'user-item-modal-price-panel--locked': isTmLocked }"
        >
          <div class="filter-row" @click.stop>
            <select
              v-model="selectedPriceListId"
              class="pricelist-select"
              :class="{ placeholder: !selectedPriceListId }"
              :disabled="isTmLocked || priceLists.length === 0"
              @change="loadPriceListItems"
            >
              <option value="">プライスリスト</option>
              <option v-for="pl in priceLists" :key="pl.id" :value="pl.id">{{ pl.label }}</option>
            </select>
            <select
              v-model="selectedBigCategory"
              class="category-select"
              :class="{ placeholder: !selectedBigCategory }"
              :disabled="isTmLocked"
              @change="handleBigCategoryChange"
            >
              <option value="">区分</option>
              <option v-for="cat in bigCategoryOptions" :key="cat.id" :value="cat.id">{{ cat.label }}</option>
            </select>
            <select
              v-model="selectedSmallCategory"
              class="category-select"
              :class="{ placeholder: !selectedSmallCategory }"
              :disabled="isTmLocked"
            >
              <option value="">大分類</option>
              <option v-for="cat in smallCategoryOptions" :key="cat.id" :value="cat.id">{{ cat.label }}</option>
            </select>
          </div>

          <div class="search-row" @click.stop>
            <input
              v-model="searchQuery"
              type="text"
              class="search-input"
              placeholder="コード・説明で検索..."
              :readonly="isTmLocked"
            />
            <button
              type="button"
              class="price-list-filter-reset-btn"
              title="区分・大分類・検索をクリア"
              :disabled="isTmLocked"
              @click.stop="resetPriceListFilters"
            >
              ✕
            </button>
          </div>

          <div class="items-list">
            <div v-if="priceListLoading" class="empty-state">読み込み中...</div>
            <div v-else-if="priceListError" class="error-state">
              {{ priceListError }}
              <button type="button" class="retry-btn" @click="loadPriceListItems">再読み込み</button>
            </div>
            <template v-else>
              <div v-if="!selectedPriceListId" class="empty-state">
                プライスリストを選択してください
              </div>
              <div v-else-if="priceListItems.length === 0" class="empty-state">
                アイテムがありません
              </div>
              <div v-else-if="filteredItems.length === 0" class="empty-state">
                検索結果がありません
              </div>
              <div
                v-else
                ref="priceListScrollEl"
                class="items-list-scroll"
              >
                <div
                  class="price-list-virtual-viewport"
                  :style="{
                    height: `${priceListVirtualizer.getTotalSize()}px`,
                    position: 'relative',
                    width: '100%',
                  }"
                >
                  <div
                    v-for="v in priceListVirtualizer.getVirtualItems()"
                    :key="v.key"
                    :ref="priceListVirtualizer.measureElement"
                    class="price-item-virtual-wrap"
                    :data-index="v.index"
                    :style="{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      width: '100%',
                      transform: `translateY(${v.start}px)`,
                    }"
                  >
                    <div
                      v-if="filteredItems[v.index]"
                      class="price-item"
                      :class="{ expanded: expandedItemId === filteredItems[v.index].id }"
                      :draggable="!isTmLocked"
                      @dragstart="handleModalPriceItemDragStart($event, filteredItems[v.index])"
                      @dragend="handleModalPriceItemDragEnd"
                      @click="onPriceListItemClick(filteredItems[v.index])"
                    >
                      <div class="item-row-1">
                        <div class="item-code">{{ filteredItems[v.index].external_code }}</div>
                        <div
                          class="item-description"
                          :class="{ truncated: expandedItemId !== filteredItems[v.index].id }"
                        >
                          {{ filteredItems[v.index].description }}
                        </div>
                      </div>
                      <div class="item-row-2">
                        <div
                          class="item-note"
                          :class="{ truncated: expandedItemId !== filteredItems[v.index].id }"
                        >
                          {{ filteredItems[v.index].additional_description || filteredItems[v.index].note || '-' }}
                        </div>
                        <div class="item-price">¥{{ formatPrice(filteredItems[v.index].unit_price) }}</div>
                        <div class="item-unit">{{ filteredItems[v.index].unit || '-' }}</div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </template>
          </div>
        </div>

        <div
          class="user-item-modal-right"
          :class="{
            'is-flash-blue': formPanelFlashBlue,
            'user-item-modal-right--readonly': isTmLocked,
            'is-drop-target': isRightPanelDropTarget
          }"
          @dragover.prevent="handleRightPanelDragOver"
          @dragleave="handleRightPanelDragLeave"
          @drop.prevent="handleRightPanelDrop"
        >
          <button type="button" class="user-item-modal-close" aria-label="閉じる" @click="requestClose">✕</button>
          <div class="user-item-modal-right-fields">
          <label class="user-item-field">
            <span class="user-item-label">名称</span>
            <input
              v-model="localDraft.description"
              type="text"
              class="user-item-input"
              :class="requiredFieldClass('description')"
              :readonly="isTmLocked"
            />
          </label>
          <label class="user-item-field">
            <span class="user-item-label">単価種別</span>
            <select
              v-model="localDraft.price_type"
              class="user-item-select"
              :class="requiredFieldClass('price_type')"
              :disabled="isTmLocked"
            >
              <option
                v-for="opt in USER_TANKA_PRICE_TYPE_OPTIONS"
                :key="'pt-' + opt.value"
                :value="opt.value"
              >{{ opt.label || '—' }}</option>
            </select>
          </label>
          <label class="user-item-field">
            <span class="user-item-label">根拠資料</span>
            <select
              v-model="localDraft.evidence"
              class="user-item-select"
              :class="requiredFieldClass('evidence')"
              :disabled="isTmLocked"
            >
              <option
                v-for="opt in USER_TANKA_EVIDENCE_OPTIONS"
                :key="'ev-' + opt.value"
                :value="opt.value"
              >{{ opt.label || '—' }}</option>
            </select>
          </label>
          <label class="user-item-field">
            <span class="user-item-label">経費区分</span>
            <select
              v-model="localDraft.keihi"
              class="user-item-select"
              :class="requiredFieldClass('keihi')"
              :disabled="isTmLocked"
            >
              <option
                v-for="opt in USER_TANKA_KEIHI_OPTIONS"
                :key="'kh-' + opt.value"
                :value="opt.value"
              >{{ opt.label || '—' }}</option>
            </select>
          </label>
          <div
            class="user-item-field user-item-field--unit"
            :class="{ 'is-flash-red': unitFieldFlashRed }"
          >
            <span class="user-item-label">単位</span>
            <button
              ref="unitTriggerRef"
              type="button"
              class="user-item-select user-item-unit-trigger"
              :class="{ 'is-open': unitDropdownOpen }"
              :aria-expanded="unitDropdownOpen"
              :disabled="isTmLocked"
              @click.stop="toggleUnitDropdown"
            >
              <span class="user-item-unit-trigger-label">{{ unitDisplayLabel }}</span>
              <span class="user-item-unit-trigger-caret" aria-hidden="true">▾</span>
            </button>
          </div>
          <Teleport to="body">
            <div
              v-if="unitDropdownOpen"
              class="user-item-unit-dropdown"
              :style="unitDropdownStyle"
              @mousedown.stop
            >
              <button
                v-for="opt in USER_TANKA_UNIT_OPTIONS"
                :key="'un-dd-' + opt.value"
                type="button"
                class="user-item-unit-option"
                :class="{ 'is-selected': localDraft.unit === opt.value }"
                @click="selectUnit(opt.value)"
              >
                {{ opt.label || '—' }}
              </button>
            </div>
          </Teleport>
          <label class="user-item-field">
            <span class="user-item-label">単価</span>
            <input
              v-model="localDraft.unit_price"
              type="text"
              class="user-item-input"
              inputmode="decimal"
              :readonly="isTmLocked"
            />
          </label>
          <label class="user-item-field">
            <span class="user-item-label">形状・寸法</span>
            <input v-model="localDraft.additional_description" type="text" class="user-item-input" :readonly="isTmLocked" />
          </label>
          <label class="user-item-field">
            <span class="user-item-label">備考</span>
            <input
              v-model="localDraft.note"
              type="text"
              class="user-item-input"
              :readonly="isTmLocked"
            />
          </label>
          </div>
          <div
            class="user-item-modal-right-actions"
            :class="{ 'user-item-modal-right-actions--tm-locked': isTmLocked }"
          >
            <button type="button" class="user-item-cancel-btn" @click="requestClose">
              {{ isTmLocked ? '閉じる' : 'キャンセル' }}
            </button>
            <button
              v-if="isTmLocked"
              type="button"
              class="user-item-reregister-btn"
              @click="handleReregister"
            >
              再登録
            </button>
            <button
              v-if="!isTmLocked"
              type="button"
              class="user-item-confirm-btn"
              @click="handleConfirm"
            >
              {{ (isEdit || isReregister) ? '反映' : '追加' }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, onUnmounted, nextTick } from 'vue'
import { useVirtualizer, measureElement } from '@tanstack/vue-virtual'
import { supabaseService } from '../services/supabase'
import { indexedDBService } from '../utils/indexedDB'
import { comparePriceListsByFiscalThenRevision } from '../utils/pickNewestPriceList'
import {
  USER_TANKA_PRICE_TYPE_OPTIONS,
  USER_TANKA_EVIDENCE_OPTIONS,
  USER_TANKA_KEIHI_OPTIONS,
  USER_TANKA_UNIT_OPTIONS,
  keihiSelectToHasExpenses,
  hasExpensesToKeihiSelect
} from '../constants/userBillingTemplateSelects.js'

const props = defineProps({
  show: { type: Boolean, default: false },
  isEdit: { type: Boolean, default: false },
  draft: { type: Object, default: null },
  /** billing_template_items.external_code（TM反映済み判定用） */
  externalCode: { type: String, default: '' },
  /** TM反映済みからの再登録（新規行として反映）モード */
  isReregister: { type: Boolean, default: false }
})

/** TM反映済み: 単価コードが 1U 形式以外（公社コード入力済み） */
const isTmLocked = computed(() => {
  const code = String(props.externalCode ?? '').trim()
  if (!code) return false
  return !/^\d+U$/i.test(code)
})

const emit = defineEmits(['close', 'confirm', 'request-close', 'reregister'])

const localDraft = ref(createEmptyDraft())
const showRequiredErrors = ref(false)
const baselineJson = ref('')

const priceLists = ref([])
const selectedPriceListId = ref('')
const priceListItems = ref([])
const priceListLoading = ref(false)
const priceListError = ref('')
const searchQuery = ref('')
const selectedBigCategory = ref('')
const selectedSmallCategory = ref('')
const allCategories = ref([])
const expandedItemId = ref(null)
const draggingPriceItem = ref(null)
const isRightPanelDropTarget = ref(false)
const MODAL_PRICE_DRAG_TYPE = 'user-item-modal-price-item'

const formPanelFlashBlue = ref(false)
const unitFieldFlashRed = ref(false)
let formFlashTimer = null
const FORM_FLASH_MS = 1200

/** 単位ドロップダウン: 表示行数上限（スクロール）・常にトリガー直下 */
const UNIT_DROPDOWN_VISIBLE_ROWS = 8
const UNIT_DROPDOWN_ROW_HEIGHT_PX = 32
const unitDropdownOpen = ref(false)
const unitTriggerRef = ref(null)
const unitDropdownStyle = ref({})

const unitDisplayLabel = computed(() => {
  const v = localDraft.value.unit
  if (!v) return '—'
  const hit = USER_TANKA_UNIT_OPTIONS.find((o) => o.value === v)
  return hit?.label || v
})

const requiredEmpty = computed(() => ({
  description: !(localDraft.value.description ?? '').trim(),
  price_type: !(localDraft.value.price_type ?? '').trim(),
  evidence: !(localDraft.value.evidence ?? '').trim(),
  keihi: !(localDraft.value.keihi ?? '').trim()
}))

function requiredFieldClass(field) {
  return { 'is-required-empty': showRequiredErrors.value && requiredEmpty.value[field] }
}

function hasRequiredEmpty() {
  return Object.values(requiredEmpty.value).some(Boolean)
}

function updateUnitDropdownPosition() {
  const el = unitTriggerRef.value
  if (!el) return
  const r = el.getBoundingClientRect()
  unitDropdownStyle.value = {
    position: 'fixed',
    top: `${r.bottom + 2}px`,
    left: `${r.left}px`,
    width: `${r.width}px`,
    maxHeight: `${UNIT_DROPDOWN_VISIBLE_ROWS * UNIT_DROPDOWN_ROW_HEIGHT_PX}px`,
    zIndex: 10060
  }
}

async function toggleUnitDropdown() {
  if (isTmLocked.value) return
  if (unitDropdownOpen.value) {
    unitDropdownOpen.value = false
    return
  }
  unitDropdownOpen.value = true
  await nextTick()
  updateUnitDropdownPosition()
}

function closeUnitDropdown() {
  unitDropdownOpen.value = false
}

function selectUnit(value) {
  localDraft.value.unit = value
  closeUnitDropdown()
}

function onDocumentPointerDown(event) {
  if (!unitDropdownOpen.value) return
  const trigger = unitTriggerRef.value
  const target = event.target
  if (trigger?.contains(target)) return
  if (target instanceof Element && target.closest('.user-item-unit-dropdown')) return
  closeUnitDropdown()
}

function onViewportChange() {
  if (unitDropdownOpen.value) updateUnitDropdownPosition()
}

onMounted(() => {
  document.addEventListener('mousedown', onDocumentPointerDown)
  window.addEventListener('resize', onViewportChange)
  window.addEventListener('scroll', onViewportChange, true)
})

onUnmounted(() => {
  document.removeEventListener('mousedown', onDocumentPointerDown)
  window.removeEventListener('resize', onViewportChange)
  window.removeEventListener('scroll', onViewportChange, true)
  clearTimeout(priceListSearchScrollDebounceTimer)
  if (formFlashTimer) {
    clearTimeout(formFlashTimer)
    formFlashTimer = null
  }
})

const bigCategoryOptions = computed(() => {
  const categoryMap = new Map()
  priceListItems.value.forEach((item) => {
    if (item.price_big_category_id && item.price_big_category_label) {
      categoryMap.set(item.price_big_category_id, item.price_big_category_label)
    }
  })
  return Array.from(categoryMap, ([id, label]) => ({ id, label }))
    .sort((a, b) => a.label.localeCompare(b.label, 'ja'))
})

const smallCategoryOptions = computed(() => {
  const categoryMap = new Map()
  let items = priceListItems.value
  if (selectedBigCategory.value) {
    items = items.filter((item) => item.price_big_category_id == selectedBigCategory.value)
  }
  items.forEach((item) => {
    if (item.price_small_category_id && item.price_small_category_label) {
      categoryMap.set(item.price_small_category_id, item.price_small_category_label)
    }
  })
  return Array.from(categoryMap, ([id, label]) => ({ id, label }))
    .sort((a, b) => a.label.localeCompare(b.label, 'ja'))
})

const filteredItems = computed(() => {
  let items = priceListItems.value

  if (selectedSmallCategory.value) {
    items = items.filter((item) => item.price_small_category_id == selectedSmallCategory.value)
  } else if (selectedBigCategory.value) {
    items = items.filter((item) => item.price_big_category_id == selectedBigCategory.value)
  }

  if (searchQuery.value.trim()) {
    const keywords = searchQuery.value
      .split(/[\s　]+/)
      .map((k) => k.trim().toLowerCase())
      .filter((k) => k.length > 0)
    if (keywords.length > 0) {
      items = items.filter((item) => {
        const searchText = [
          item.external_code || '',
          item.description || '',
          item.note || '',
          item.additional_description || ''
        ].join(' ').toLowerCase()
        return keywords.every((keyword) => searchText.includes(keyword))
      })
    }
  }

  return items.slice().sort((a, b) => {
    const codeA = (a.external_code || '').toString()
    const codeB = (b.external_code || '').toString()
    return codeA.localeCompare(codeB, 'ja', { numeric: true })
  })
})

const priceListScrollEl = ref(null)

const priceListVirtualizer = useVirtualizer(
  computed(() => ({
    count: filteredItems.value.length,
    getScrollElement: () => priceListScrollEl.value,
    estimateSize: () => 84,
    overscan: 15,
    measureElement,
    useAnimationFrameWithResizeObserver: true,
    getItemKey: (index) => {
      const it = filteredItems.value[index]
      return it?.id ?? `idx-${index}`
    }
  }))
)

function scrollPriceListScrollTop() {
  nextTick(() => {
    priceListScrollEl.value?.scrollTo({ top: 0, behavior: 'auto' })
    priceListVirtualizer.value?.scrollToOffset(0, { behavior: 'auto' })
  })
}

watch(
  () => [selectedBigCategory.value, selectedSmallCategory.value, selectedPriceListId.value],
  () => {
    scrollPriceListScrollTop()
  }
)

let priceListSearchScrollDebounceTimer = null
watch(searchQuery, () => {
  clearTimeout(priceListSearchScrollDebounceTimer)
  priceListSearchScrollDebounceTimer = setTimeout(() => {
    priceListSearchScrollDebounceTimer = null
    scrollPriceListScrollTop()
  }, 280)
})

function createEmptyDraft() {
  return {
    description: '',
    price_type: '',
    evidence: '',
    keihi: '',
    unit: '',
    additional_description: '',
    note: '',
    unit_price: ''
  }
}

function cloneDraft(source) {
  const base = createEmptyDraft()
  if (!source) return base
  return {
    ...base,
    description: source.description ?? '',
    price_type: source.price_type ?? '',
    evidence: source.evidence ?? '',
    keihi: hasExpensesToKeihiSelect(source.has_expenses),
    unit: source.unit ?? '',
    additional_description: source.additional_description ?? '',
    note: source.note ?? '',
    unit_price: formatUnitPriceInput(source.unit_price)
  }
}

function formatUnitPriceInput(value) {
  if (value === null || value === undefined || value === '') return ''
  const n = Number(String(value).replace(/,/g, '').trim())
  if (!Number.isFinite(n)) return String(value)
  return n.toLocaleString('ja-JP')
}

function parseUnitPriceInput(value) {
  if (value === '' || value == null) return null
  const n = Number(String(value).replace(/,/g, '').trim())
  return Number.isFinite(n) ? n : null
}

function clearFormFlash() {
  formPanelFlashBlue.value = false
  unitFieldFlashRed.value = false
  if (formFlashTimer) {
    clearTimeout(formFlashTimer)
    formFlashTimer = null
  }
}

function triggerVacantApplyFlash(unitMismatch) {
  clearFormFlash()
  formPanelFlashBlue.value = true
  unitFieldFlashRed.value = unitMismatch
  formFlashTimer = setTimeout(() => {
    formPanelFlashBlue.value = false
    unitFieldFlashRed.value = false
    formFlashTimer = null
  }, FORM_FLASH_MS)
}

function isDirty() {
  return JSON.stringify(localDraft.value) !== baselineJson.value
}

async function loadCategories() {
  try {
    const categories = await indexedDBService.master_data
      .where('table_name')
      .equals('master_price_categories')
      .and((item) => item.is_active === true)
      .toArray()
    allCategories.value = categories.map((item) => ({
      id: item.id,
      label: item.label,
      parent_id: item.parent_id || null
    }))
  } catch (err) {
    console.error('Failed to load price categories:', err)
  }
}

async function loadPriceLists() {
  if (isTmLocked.value) {
    selectedPriceListId.value = ''
    priceListItems.value = []
    priceListError.value = ''
    return
  }
  try {
    const raw = await supabaseService.getPriceLists(null, 'large')
    priceLists.value = (raw || []).slice().sort(comparePriceListsByFiscalThenRevision)

    const idSet = new Set(priceLists.value.map((p) => String(p.id)))
    const cur = String(selectedPriceListId.value ?? '')
    const needPick = priceLists.value.length > 0 && (!cur || !idSet.has(cur))

    if (priceLists.value.length === 0) {
      selectedPriceListId.value = ''
      priceListItems.value = []
    } else if (needPick) {
      selectedPriceListId.value = priceLists.value[0].id
      await loadPriceListItems()
    }
  } catch (err) {
    console.error('Failed to load large price lists:', err)
    priceListError.value = 'プライスリストの読み込みに失敗しました'
  }
}

async function loadPriceListItems() {
  if (!selectedPriceListId.value) {
    priceListItems.value = []
    return
  }

  if (!allCategories.value.length) {
    await loadCategories()
  }

  selectedBigCategory.value = ''
  selectedSmallCategory.value = ''
  searchQuery.value = ''
  expandedItemId.value = null

  priceListLoading.value = true
  priceListError.value = ''
  try {
    const raw = await supabaseService.getPriceListItems(selectedPriceListId.value)
    priceListItems.value = (raw || []).map((item) => {
      const bigCategory = allCategories.value.find((c) => c.id == item.price_big_category_id)
      const smallCategory = allCategories.value.find((c) => c.id == item.price_small_category_id)
      return {
        ...item,
        price_big_category_label: item.price_big_category_label || bigCategory?.label || '',
        price_small_category_label: item.price_small_category_label || smallCategory?.label || ''
      }
    })
  } catch (err) {
    console.error('Failed to load price list items:', err)
    priceListError.value = 'プライスリストアイテムの読み込みに失敗しました'
    priceListItems.value = []
  } finally {
    priceListLoading.value = false
    scrollPriceListScrollTop()
  }
}

function handleBigCategoryChange() {
  const sid = selectedSmallCategory.value
  if (!sid) return
  const ok = smallCategoryOptions.value.some((c) => c.id == sid)
  if (!ok) selectedSmallCategory.value = ''
}

function resetPriceListFilters() {
  selectedBigCategory.value = ''
  selectedSmallCategory.value = ''
  searchQuery.value = ''
  expandedItemId.value = null
  scrollPriceListScrollTop()
}

function resolveUnitFromPriceList(plUnit) {
  const u = String(plUnit ?? '').trim()
  if (!u) return ''
  const hit = USER_TANKA_UNIT_OPTIONS.find((o) => o.value === u || o.label === u)
  return hit?.value ?? ''
}

function vacantUnitPriceFromPriceList(unitPrice) {
  const n = Number(unitPrice)
  if (!Number.isFinite(n)) return 0
  return Math.floor(n * 0.9)
}

/** 左PL: 選択状態で再クリック/タップ → 空家単価を右フォームへ反映 */
function applyVacantPriceFromPriceList(item) {
  if (!item) return
  const discounted = vacantUnitPriceFromPriceList(item.unit_price)
  const code = String(item.external_code ?? '').trim()
  const plUnit = String(item.unit ?? '').trim()
  const resolvedUnit = resolveUnitFromPriceList(item.unit)
  const unitMismatch = Boolean(plUnit && !resolvedUnit)
  localDraft.value.description = item.description ?? ''
  localDraft.value.price_type = '材工'
  localDraft.value.evidence = '刊行物'
  localDraft.value.keihi = '2'
  localDraft.value.unit = resolvedUnit
  localDraft.value.unit_price = formatUnitPriceInput(discounted)
  localDraft.value.note = `空家単価(${code}) ¥${item.unit_price ?? ''}×0.9`
  triggerVacantApplyFlash(unitMismatch)
}

function onPriceListItemClick(item) {
  if (isTmLocked.value) return
  if (!item?.id) return
  if (expandedItemId.value !== item.id) {
    expandedItemId.value = item.id
    return
  }
  expandedItemId.value = null
  applyVacantPriceFromPriceList(item)
}

function handleModalPriceItemDragStart(event, item) {
  if (isTmLocked.value) {
    event.preventDefault()
    return
  }
  draggingPriceItem.value = item
  event.dataTransfer.effectAllowed = 'copy'
  event.dataTransfer.setData(
    'text/plain',
    JSON.stringify({
      type: MODAL_PRICE_DRAG_TYPE,
      id: item.id,
      external_code: item.external_code
    })
  )
}

function handleModalPriceItemDragEnd() {
  draggingPriceItem.value = null
  isRightPanelDropTarget.value = false
}

function resolveModalPriceItemFromDrop(event) {
  if (draggingPriceItem.value) return draggingPriceItem.value
  let raw = ''
  try {
    raw = event.dataTransfer?.getData?.('text/plain') || ''
  } catch {
    return null
  }
  if (!raw) return null
  try {
    const d = JSON.parse(raw)
    if (d?.type !== MODAL_PRICE_DRAG_TYPE) return null
    if (d.id != null) {
      const byId = priceListItems.value.find((i) => i.id == d.id)
      if (byId) return byId
    }
    const code = String(d.external_code ?? '').trim()
    if (code) {
      return priceListItems.value.find((i) => String(i.external_code) === code) || null
    }
  } catch {
    return null
  }
  return null
}

function handleRightPanelDragOver(event) {
  if (isTmLocked.value || !draggingPriceItem.value) return
  event.dataTransfer.dropEffect = 'copy'
  isRightPanelDropTarget.value = true
}

function handleRightPanelDragLeave(event) {
  const panel = event.currentTarget
  const related = event.relatedTarget
  if (related && panel.contains(related)) return
  isRightPanelDropTarget.value = false
}

function handleRightPanelDrop(event) {
  if (isTmLocked.value) return
  const item = resolveModalPriceItemFromDrop(event)
  draggingPriceItem.value = null
  isRightPanelDropTarget.value = false
  if (!item) return
  expandedItemId.value = null
  applyVacantPriceFromPriceList(item)
}

function formatPrice(price) {
  if (price === null || price === undefined || price === '') return '0'
  return Number(price).toLocaleString('ja-JP')
}

function normalizeForEmit(draft) {
  return {
    description: (draft.description ?? '').trim(),
    price_type: draft.price_type?.trim() || null,
    evidence: draft.evidence?.trim() || null,
    unit: draft.unit?.trim() || null,
    additional_description: draft.additional_description?.trim() || null,
    note: (draft.note ?? '').trim() || null,
    has_expenses: keihiSelectToHasExpenses(draft.keihi),
    unit_price: parseUnitPriceInput(draft.unit_price)
  }
}

async function initPricePanel() {
  priceListError.value = ''
  if (isTmLocked.value) {
    selectedPriceListId.value = ''
    priceListItems.value = []
    selectedBigCategory.value = ''
    selectedSmallCategory.value = ''
    searchQuery.value = ''
    expandedItemId.value = null
    priceLists.value = []
    return
  }
  await loadCategories()
  await loadPriceLists()
}

watch(
  () => [props.show, props.draft],
  async () => {
    if (!props.show) {
      closeUnitDropdown()
      clearFormFlash()
      showRequiredErrors.value = false
      return
    }
    showRequiredErrors.value = false
    localDraft.value = cloneDraft(props.draft)
    baselineJson.value = JSON.stringify(localDraft.value)
    expandedItemId.value = null
    await initPricePanel()
  },
  { immediate: true, deep: true }
)

function requestClose() {
  emit('request-close', isDirty())
}

function handleReregister() {
  emit('reregister')
}

function handleConfirm() {
  showRequiredErrors.value = true
  if (hasRequiredEmpty()) return
  showRequiredErrors.value = false
  emit('confirm', normalizeForEmit(localDraft.value))
}
</script>

