<script setup>
import { ref, shallowRef, computed, watch, onUnmounted, nextTick } from 'vue'
import { useBoardOverlayTransform } from '../composables/useBoardOverlayTransform.js'
import { compositeVideoFrameWithBoard, viewportRectToFrameContentLocal } from '../utils/boardComposite.js'
import { renderBoardMasterCanvas, drawBoardMasterIntoDestination } from '../utils/boardTemplates.js'
import { BOARD_SIZE_PRESETS, BOARD_VIDEO_SPACE_REF } from '../utils/boardTemplateConfig.js'
import { indexedDBService } from '../utils/indexedDB.js'
import { processBoardCaptureForUpload } from '../utils/imageResize.js'

const props = defineProps({
  modelValue: { type: Boolean, default: false },
  workId: { type: String, required: true },
  workCategoryId: { type: String, default: '' },
  targetSlotId: { type: String, default: null },
  /** works.kind: large → あき家補修工事 / small → 小口修繕工事 */
  workKind: { type: String, default: '' },
  /** 現場名（name-building-room。workDisplayName とは別で小口/あき家なし） */
  housingName: { type: String, default: '' },
  /** master_companies.name + company_type */
  masterCompanyName: { type: String, default: '' },
  /** カテゴリーに属さない導線用: works.display_text */
  workDisplayText: { type: String, default: '' },
  /** カテゴリー名（フォルダ名）。workCategoryId があるときの撮影内容 */
  workCategoryLabel: { type: String, default: '' },
  uploadHandler: {
    type: Function,
    required: true
  }
})

const emit = defineEmits(['update:modelValue', 'closed'])

/** 黒板 UI: 0=240×180 / 1=320×240 / 2=400×300 / 3=非表示（ツールバーボタンで順に切替） */
const BOARD_UI_CYCLE_HIDDEN = 3

/** true = 横向き撮影モード（黒板＋文字を 90° 回転して表示・JPEG にも反映） */
const boardRotated90 = ref(false)

const boardOrientationTitle = computed(() =>
  boardRotated90.value
    ? '黒板向き: 横向き（タップで縦向きに戻す）'
    : '黒板向き: 縦向き（タップで横向き＝黒板90°回転）'
)

function toggleBoardOrientation() {
  boardRotated90.value = !boardRotated90.value
  nextTick(() => {
    requestAnimationFrame(() => {
      clampPosition()
      paintBoardPreview()
    })
  })
}

const rootRef = ref(null)
const frameWrapRef = ref(null)
const frameRef = ref(null)
const videoRef = ref(null)
const boardRef = ref(null)
const boardVisualRef = ref(null)
const boardPreviewCanvasRef = ref(null)

const framePixelStyle = ref({ width: '400px', height: '300px' })

/** 枠・ビデオ寸法はリアクティブでないため、layoutFrame / loadedmetadata でインクリメントして黒板スケールを再計算 */
const boardScaleLayoutTick = ref(0)
const boardVideoIntrinsic = ref({ w: 0, h: 0 })

const cameraError = ref(null)

/** 未送信（saved_local / failed）の上限。超えると保存時に古いものを 100 件ずつ削除 */
const pendingBoardCaptureMax = 500
const pendingPruneBatch = 100

/** 撮影直後: 回転前プレビュー表示中。〇で IndexedDB 保存、✕で破棄 */
const captureReviewPending = ref(false)
const captureReviewObjectUrl = ref('')
/** shallow: 中の Blob / board を深い reactive（Proxy）にしない。IndexedDB が DataCloneError になるのを防ぐ */
const captureReviewDraft = shallowRef(null)

const showPendingLimitModal = ref(false)
const isCommittingReview = ref(false)

const boardUiCycle = ref(BOARD_UI_CYCLE_HIDDEN)

const boardVisible = computed(() => boardUiCycle.value < BOARD_UI_CYCLE_HIDDEN)

const activeBoardPreset = computed(() => {
  const i = boardUiCycle.value
  if (i >= BOARD_UI_CYCLE_HIDDEN) return null
  return BOARD_SIZE_PRESETS[i] ?? BOARD_SIZE_PRESETS[0]
})

/**
 * 映像 contain と同じ倍率（ビデオ 1px → プレビュー枠内の CSS px）。
 * プリセット width/height は videoWidth×videoHeight 上のピクセル（1280×960 想定で調整）。
 */
const videoToFrameScale = computed(() => {
  boardScaleLayoutTick.value
  const fr = frameRef.value
  const vid = videoRef.value
  const vw = boardVideoIntrinsic.value.w || vid?.videoWidth
  const vh = boardVideoIntrinsic.value.h || vid?.videoHeight
  if (!fr || !vw || !vh) return 1
  const boxW = fr.clientWidth
  const boxH = fr.clientHeight
  if (!boxW || !boxH) return 1
  return Math.min(boxW / vw, boxH / vh)
})

/** 黒板のプレビュー上の CSS サイズ（ビデオ空間ピクセル × contain 倍率） */
const boardDisplayPx = computed(() => {
  const s = videoToFrameScale.value
  const p = activeBoardPreset.value ?? BOARD_SIZE_PRESETS[0]
  return {
    width: p.width * s,
    height: p.height * s
  }
})

function onBoardVideoMetrics() {
  const v = videoRef.value
  if (v?.videoWidth && v?.videoHeight) {
    boardVideoIntrinsic.value = { w: v.videoWidth, h: v.videoHeight }
  }
  nextTick(() => {
    requestAnimationFrame(() => {
      clampPosition()
      paintBoardPreview()
    })
  })
}

/** 黒板を 90° 回転表示するときは AABB が入れ替わるのでクランプ用サイズも入れ替え */
const boardSizeForClamp = computed(() => {
  const d = boardDisplayPx.value
  if (boardRotated90.value) {
    return { width: d.height, height: d.width }
  }
  return { width: d.width, height: d.height }
})

const { x: boardX, y: boardY, scale: boardScale, clampPosition, onTouchStart, onTouchMove, onTouchEnd } =
  useBoardOverlayTransform(
    frameRef,
    boardSizeForClamp,
    { x: 2, y: 80, scale: 1 },
    rootRef,
    {
      minScale: 1,
      maxScale: 1,
      edgeMargin: 0,
      horizontalEdgeInset: 3,
      verticalEdgeInset: 2,
      verticalEdgeInsetBottom: 5,
      outerSize: () => {
        const d = boardDisplayPx.value
        return { width: d.width, height: d.height }
      },
      boardRotated90Ref: boardRotated90,
      disablePinch: true
    }
  )

let boardTouchCleanup = null
const touchOpts = { passive: false }

function bindBoardTouch() {
  unbindBoardTouch()
  const el = boardRef.value
  if (!el || !props.modelValue || !boardVisible.value) return
  el.addEventListener('touchstart', onTouchStart, touchOpts)
  el.addEventListener('touchmove', onTouchMove, touchOpts)
  el.addEventListener('touchend', onTouchEnd, touchOpts)
  el.addEventListener('touchcancel', onTouchEnd, touchOpts)
  boardTouchCleanup = () => {
    el.removeEventListener('touchstart', onTouchStart, touchOpts)
    el.removeEventListener('touchmove', onTouchMove, touchOpts)
    el.removeEventListener('touchend', onTouchEnd, touchOpts)
    el.removeEventListener('touchcancel', onTouchEnd, touchOpts)
  }
}

function unbindBoardTouch() {
  boardTouchCleanup?.()
  boardTouchCleanup = null
}

let resizeObserver = null
let layoutRetryTimers = []
let layoutZeroRetryTimer = null

function clearLayoutRetryTimers() {
  layoutRetryTimers.forEach((id) => clearTimeout(id))
  layoutRetryTimers = []
  clearTimeout(layoutZeroRetryTimer)
  layoutZeroRetryTimer = null
}

function scheduleLayoutFrameRetries() {
  clearLayoutRetryTimers()
  const run = () => {
    layoutFrame()
    requestAnimationFrame(() => {
      layoutFrame()
      requestAnimationFrame(() => layoutFrame())
    })
  }
  nextTick(run)
  layoutRetryTimers.push(setTimeout(run, 80))
  layoutRetryTimers.push(setTimeout(run, 300))
}

function layoutFrame() {
  const wrap = frameWrapRef.value
  if (!wrap) return
  const W = wrap.clientWidth
  const H = wrap.clientHeight
  // 初回は flex 計算前で 0 になり得る → 再試行で枠を必ず出す
  if (W < 8 || H < 8) {
    clearTimeout(layoutZeroRetryTimer)
    layoutZeroRetryTimer = setTimeout(() => layoutFrame(), 32)
    return
  }
  // 縦固定 UI: 枠は常に幅:高さ = 3:4。映像は contain で枠内に収め、本体カメラに近い画角（クロップしない）
  const ar = 3 / 4
  let fw
  let fh
  if (W / H >= ar) {
    fh = H
    fw = fh * ar
  } else {
    fw = W
    fh = fw / ar
  }
  framePixelStyle.value = {
    width: `${Math.floor(fw)}px`,
    height: `${Math.floor(fh)}px`
  }
  boardScaleLayoutTick.value++
  nextTick(() => {
    clampPosition()
    /** 枠サイズ・contain 倍率が変わるたびに再描画しないと、黒板枠だけ伸びて文字スケールが古いまま残る */
    if (props.modelValue && boardVisible.value) paintBoardPreview()
  })
}

const fields = ref({
  projectName: '',
  companyName: '',
  siteName: '',
  subject: ''
})

const showEdit = ref(false)

const isCapturing = ref(false)
const isUploadingBatch = ref(false)
const sessionPhotos = ref([])
const thumbUrls = ref({})

/** 合成は getBoundingClientRect 基準。見た目サイズは boardDisplayPx（ビデオ×contain 連動） */
const boardOuterStyle = computed(() => {
  const d = boardDisplayPx.value
  return {
    width: `${d.width}px`,
    height: `${d.height}px`,
    transform: `translate(${boardX.value}px, ${boardY.value}px)`,
    transformOrigin: 'top left'
  }
})

const boardCycleTitle = computed(() => {
  if (!boardVisible.value) return '黒板: 非表示（タップで小）'
  const labels = ['小 240×180px', '中 320×240px', '大 400×300px']
  const i = boardUiCycle.value
  const ref = `${BOARD_VIDEO_SPACE_REF.width}×${BOARD_VIDEO_SPACE_REF.height}`
  return `黒板: ${labels[i] ?? labels[0]}（ビデオ ${ref} 相当のピクセル比・タップで切替）`
})

function cycleBoardDisplay() {
  boardUiCycle.value = (boardUiCycle.value + 1) % (BOARD_UI_CYCLE_HIDDEN + 1)
}

let boardPreviewPaintToken = 0
/** フル解像度マスターとキャッシュキー（fields / プリセット変更で無効化） */
const boardPreviewMasterState = { key: '', canvas: null }
let boardPreviewFieldsDebounceTimer = null

function boardPreviewMasterCacheKey(preset) {
  if (!preset) return ''
  return JSON.stringify({
    id: preset.id,
    tpl: preset.templatePublicFile,
    tr: preset.templateRef,
    projectName: fields.value.projectName,
    companyName: fields.value.companyName,
    siteName: fields.value.siteName,
    subject: fields.value.subject
  })
}

async function paintBoardPreviewImpl() {
  if (!boardVisible.value) return
  const canvas = boardPreviewCanvasRef.value
  if (!canvas) return
  const preset = activeBoardPreset.value
  if (!preset) return
  const token = ++boardPreviewPaintToken
  await nextTick()
  /** 回転は CSS で inner のみ。キャンバスは常に外枠＝未回転の論理サイズ（テンプレ 4:3 と一致。visual の AABB だと縦長に引き伸ばされ文字比が崩れる） */
  const { width: w, height: h } = boardDisplayPx.value
  const dpr = Math.min(2, typeof window !== 'undefined' ? window.devicePixelRatio || 1 : 1)
  canvas.width = Math.max(1, Math.round(w * dpr))
  canvas.height = Math.max(1, Math.round(h * dpr))
  canvas.style.width = `${w}px`
  canvas.style.height = `${h}px`
  const ctx = canvas.getContext('2d')
  if (!ctx) return
  const cacheKey = boardPreviewMasterCacheKey(preset)
  if (boardPreviewMasterState.key !== cacheKey || !boardPreviewMasterState.canvas) {
    try {
      const master = await renderBoardMasterCanvas(fields.value, 'default', {
        fieldLayout: preset.fieldLayout,
        fixedTexts: preset.fixedTexts,
        templatePublicFile: preset.templatePublicFile,
        templateRef: preset.templateRef
      })
      if (token !== boardPreviewPaintToken) return
      boardPreviewMasterState.canvas = master
      boardPreviewMasterState.key = cacheKey
    } catch (e) {
      console.warn('[BoardCameraCapture] 黒板プレビュー描画失敗', e)
      return
    }
  }
  if (token !== boardPreviewPaintToken) return
  ctx.setTransform(1, 0, 0, 1, 0, 0)
  ctx.scale(dpr, dpr)
  drawBoardMasterIntoDestination(ctx, boardPreviewMasterState.canvas, 0, 0, w, h)
}

function paintBoardPreview() {
  void paintBoardPreviewImpl()
}

function schedulePaintBoardPreviewFromFields() {
  if (boardPreviewFieldsDebounceTimer) clearTimeout(boardPreviewFieldsDebounceTimer)
  boardPreviewFieldsDebounceTimer = setTimeout(() => {
    boardPreviewFieldsDebounceTimer = null
    void paintBoardPreviewImpl()
  }, 80)
}

const isBusy = computed(
  () =>
    isCapturing.value ||
    isUploadingBatch.value ||
    captureReviewPending.value ||
    isCommittingReview.value
)
const busyLabel = computed(() => {
  if (isUploadingBatch.value) return 'アップロード中…'
  if (isCommittingReview.value) return '保存処理中…'
  if (isCapturing.value) return '保存中…'
  if (captureReviewPending.value) return '保存するか破棄を選んでください'
  return ''
})

const sessionCount = computed(() => sessionPhotos.value.length)
const pendingSendCount = computed(() =>
  sessionPhotos.value.filter((p) => p.status === 'saved_local' || p.status === 'failed').length
)

function statusLabel(st) {
  const m = {
    saved_local: '未送信',
    uploading: '送信中',
    uploaded: '送信済',
    failed: '送信失敗'
  }
  return m[st] || st
}

/** サムネイルダブルタップ / ダブルクリックで全画面プレビュー */
const previewPhoto = ref(null)
const lastThumbTap = ref({ time: 0, id: null })

function openPhotoPreview(p) {
  if (!p?.blob) return
  closePhotoPreview()
  previewPhoto.value = { id: p.id, url: URL.createObjectURL(p.blob) }
}

function closePhotoPreview() {
  if (previewPhoto.value?.url) {
    URL.revokeObjectURL(previewPhoto.value.url)
  }
  previewPhoto.value = null
}

function onThumbTouchEnd(p, e) {
  if (!p?.blob || e.changedTouches?.length !== 1) return
  const now = Date.now()
  if (lastThumbTap.value.id === p.id && now - lastThumbTap.value.time < 380) {
    openPhotoPreview(p)
    lastThumbTap.value = { time: 0, id: null }
  } else {
    lastThumbTap.value = { time: now, id: p.id }
  }
}

/** オープン時: 工事名・現場名・撮影内容を案件データから自動入力（撮影内容＝display_text ＋ フォルダ名） */
function applyBoardAutoFields() {
  const kind = props.workKind
  if (kind === 'large') {
    fields.value.projectName = 'あき家補修工事'
  } else if (kind === 'small') {
    fields.value.projectName = '小口修繕工事'
  } else {
    fields.value.projectName = ''
  }
  fields.value.companyName = props.masterCompanyName || ''
  fields.value.siteName = props.housingName || ''
  const line1 = props.workDisplayText || ''
  const catId = props.workCategoryId
  const hasCategory = catId != null && String(catId).trim() !== ''
  const line2 = hasCategory ? String(props.workCategoryLabel || '').trim() : ''
  fields.value.subject = line2 ? (line1 ? `${line1}\n${line2}` : line2) : line1
}

async function loadSession() {
  const rows = await indexedDBService.listBoardCapturePhotosByWork(props.workId)
  sessionPhotos.value = rows
  for (const p of rows) {
    if (p.thumbnailBlob) {
      if (thumbUrls.value[p.id]) URL.revokeObjectURL(thumbUrls.value[p.id])
      thumbUrls.value[p.id] = URL.createObjectURL(p.thumbnailBlob)
    } else if (p.blob) {
      if (thumbUrls.value[p.id]) URL.revokeObjectURL(thumbUrls.value[p.id])
      thumbUrls.value[p.id] = URL.createObjectURL(p.blob)
    }
  }
}

function revokeThumbs() {
  Object.values(thumbUrls.value).forEach((u) => URL.revokeObjectURL(u))
  thumbUrls.value = {}
}

const streamRef = ref(null)

/** バックライト（torch）: 端末が対応しているときのみ有効 */
const torchAvailable = ref(false)
/** off | capture（撮影ボタン押下中のみ） | always（常時点灯） */
const torchMode = ref('off')

const TORCH_SEQUENCE = ['off', 'capture', 'always']

const torchCycleDisabled = computed(
  () => isBusy.value || !!cameraError.value || !streamRef.value || !torchAvailable.value
)

const torchButtonTitle = computed(() => {
  if (!streamRef.value) return 'カメラ起動後にライトを切り替えられます'
  if (!torchAvailable.value) return 'この端末・ブラウザではライト制御に非対応です'
  if (torchMode.value === 'off') return 'ライト: オフ（タップで撮影時のみ点灯）'
  if (torchMode.value === 'capture') return 'ライト: 撮影時のみ点灯（タップで常時点灯）'
  return 'ライト: 常時点灯（タップでオフ）'
})

const torchButtonClass = computed(() => ({
  'board-tb-btn--torch-off': torchMode.value === 'off' && torchAvailable.value,
  'board-tb-btn--torch-capture': torchMode.value === 'capture',
  'board-tb-btn--torch-always': torchMode.value === 'always'
}))

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms))
}

function getVideoTrack() {
  return streamRef.value?.getVideoTracks?.()[0] ?? null
}

function refreshTorchCapability() {
  const track = getVideoTrack()
  const sup = navigator.mediaDevices?.getSupportedConstraints?.() ?? {}
  const caps = track?.getCapabilities?.() ?? {}
  torchAvailable.value = sup.torch === true && caps && Object.prototype.hasOwnProperty.call(caps, 'torch')
}

async function applyTorch(on) {
  const track = getVideoTrack()
  if (!track?.applyConstraints || !torchAvailable.value) return
  try {
    await track.applyConstraints({ torch: on })
  } catch (e) {
    console.warn('torch applyConstraints', e)
  }
}

async function syncTorchToMode() {
  if (!torchAvailable.value || !streamRef.value) return
  if (torchMode.value === 'always') await applyTorch(true)
  else await applyTorch(false)
}

function cycleTorchMode() {
  if (torchCycleDisabled.value) return
  const i = TORCH_SEQUENCE.indexOf(torchMode.value)
  torchMode.value = TORCH_SEQUENCE[(i + 1) % TORCH_SEQUENCE.length]
}

watch(torchMode, () => {
  if (props.modelValue && streamRef.value) syncTorchToMode()
})

/**
 * aspectRatio 指定なしで背面カメラを取得（通常オープンとテストで共通）
 * ideal 1280×960 → 失敗時は facingMode のみ。端末は縦持ちで 960×1280 など入れ替えて返すことがある
 */
async function getBoardCameraUserMediaStream() {
  const maxW = 3840
  const maxH = 3840
  try {
    return await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: { ideal: 'environment' },
        width: { ideal: 1280, max: maxW },
        height: { ideal: 960, max: maxH }
      },
      audio: false
    })
  } catch {
    return await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: 'environment' } },
      audio: false
    })
  }
}

async function openCamera() {
  cameraError.value = null
  if (!navigator.mediaDevices?.getUserMedia) {
    cameraError.value = 'このブラウザではカメラを利用できません'
    return
  }
  try {
    const s = await getBoardCameraUserMediaStream()
    streamRef.value = s
    refreshTorchCapability()
    await syncTorchToMode()
    await nextTick()
    if (videoRef.value) {
      videoRef.value.srcObject = s
      await videoRef.value.play().catch(() => {})
      await nextTick()
      onBoardVideoMetrics()
    }
  } catch (e) {
    console.error(e)
    cameraError.value = e?.message || 'カメラの起動に失敗しました'
  }
}

function clearCaptureReview() {
  if (captureReviewObjectUrl.value) {
    URL.revokeObjectURL(captureReviewObjectUrl.value)
    captureReviewObjectUrl.value = ''
  }
  captureReviewDraft.value = null
  captureReviewPending.value = false
}

/** IndexedDB structured clone 用に黒板メタだけプレーンオブジェクト化（Vue Proxy を除去） */
function cloneBoardForIndexedDb(board) {
  if (!board || typeof board !== 'object') return {}
  try {
    return JSON.parse(JSON.stringify(board))
  } catch {
    return {
      templateId: board.templateId,
      x: board.x,
      y: board.y,
      scale: board.scale,
      rotateBoardCw90: board.rotateBoardCw90,
      layoutWidth: board.layoutWidth,
      layoutHeight: board.layoutHeight,
      boardPresetId: board.boardPresetId,
      fields: { ...(board.fields || {}) }
    }
  }
}

function isPendingBoardCaptureStatus(st) {
  return st === 'saved_local' || st === 'failed'
}

async function countPendingBoardCapturesInDb() {
  const rows = await indexedDBService.listBoardCapturePhotosByWork(props.workId)
  return rows.filter((p) => isPendingBoardCaptureStatus(p.status)).length
}

/** 未送信が上限以上なら古い順に pendingPruneBatch 件ずつ削除（ループ） */
async function pruneOldestPendingBoardCapturesUntilUnderLimit() {
  while (true) {
    const rows = await indexedDBService.listBoardCapturePhotosByWork(props.workId)
    const pending = rows.filter((p) => isPendingBoardCaptureStatus(p.status))
    if (pending.length < pendingBoardCaptureMax) break
    const toDelete = pending.slice(0, pendingPruneBatch)
    for (const p of toDelete) {
      await indexedDBService.deleteBoardCapturePhoto(p.id)
      if (thumbUrls.value[p.id]) {
        URL.revokeObjectURL(thumbUrls.value[p.id])
        delete thumbUrls.value[p.id]
      }
    }
    const delIds = new Set(toDelete.map((p) => p.id))
    sessionPhotos.value = sessionPhotos.value.filter((x) => !delIds.has(x.id))
  }
}

async function commitCaptureReviewWithPrune() {
  const d = captureReviewDraft.value
  if (!d || isCommittingReview.value) return
  isCommittingReview.value = true
  cameraError.value = null
  try {
    await pruneOldestPendingBoardCapturesUntilUnderLimit()

    const id = crypto.randomUUID()
    const record = {
      id,
      work_id: props.workId,
      createdAt: d.createdAt,
      status: 'saved_local',
      uploadRetryCount: 0,
      fileName: d.fileName,
      mimeType: 'image/jpeg',
      width: d.width,
      height: d.height,
      blob: d.blob,
      thumbnailBlob: d.thumbnailBlob ?? null,
      sthumbBlob: d.sthumbBlob ?? null,
      rotation: typeof d.rotation === 'number' ? d.rotation : 0,
      isStandardAspectRatio: !!d.isStandardAspectRatio,
      board: cloneBoardForIndexedDb(d.board),
      savedToDevice: false,
      uploadedAt: null,
      serverResponse: null,
      errorMessage: null
    }
    await indexedDBService.saveBoardCapturePhoto(record)
    if (d.thumbnailBlob) {
      thumbUrls.value[id] = URL.createObjectURL(d.thumbnailBlob)
    } else {
      thumbUrls.value[id] = URL.createObjectURL(d.blob)
    }
    sessionPhotos.value = [...sessionPhotos.value, record]
    clearCaptureReview()
  } catch (e) {
    console.error(e)
    cameraError.value = e?.message || '保存に失敗しました'
  } finally {
    isCommittingReview.value = false
  }
}

async function confirmCaptureReview() {
  if (!captureReviewDraft.value || isCommittingReview.value) return
  const n = await countPendingBoardCapturesInDb()
  if (n >= pendingBoardCaptureMax) {
    showPendingLimitModal.value = true
    return
  }
  await commitCaptureReviewWithPrune()
}

function cancelPendingLimitModal() {
  if (isCommittingReview.value) return
  showPendingLimitModal.value = false
}

async function confirmPendingLimitModal() {
  showPendingLimitModal.value = false
  await commitCaptureReviewWithPrune()
}

function discardCaptureReview() {
  clearCaptureReview()
}

async function closeCamera() {
  await applyTorch(false).catch(() => {})
  torchAvailable.value = false
  if (videoRef.value) videoRef.value.srcObject = null
  if (streamRef.value) {
    streamRef.value.getTracks().forEach((t) => t.stop())
    streamRef.value = null
  }
}

function setupResizeObserver() {
  teardownResizeObserver()
  const el = frameWrapRef.value
  if (!el) return
  resizeObserver = new ResizeObserver(() => layoutFrame())
  resizeObserver.observe(el)
}

function teardownResizeObserver() {
  resizeObserver?.disconnect()
  resizeObserver = null
}

watch(
  () => props.modelValue,
  async (open) => {
    if (open) {
      torchMode.value = 'off'
      boardRotated90.value = false
      boardUiCycle.value = BOARD_UI_CYCLE_HIDDEN
      boardScale.value = 1
      boardVideoIntrinsic.value = { w: 0, h: 0 }
      boardPreviewMasterState.key = ''
      boardPreviewMasterState.canvas = null
      applyBoardAutoFields()
      await nextTick()
      setupResizeObserver()
      scheduleLayoutFrameRetries()
      await openCamera()
      await loadSession()
      scheduleLayoutFrameRetries()
      await nextTick()
      await paintBoardPreview()
      bindBoardTouch()
    } else {
      if (boardPreviewFieldsDebounceTimer) {
        clearTimeout(boardPreviewFieldsDebounceTimer)
        boardPreviewFieldsDebounceTimer = null
      }
      boardPreviewMasterState.key = ''
      boardPreviewMasterState.canvas = null
      clearLayoutRetryTimers()
      unbindBoardTouch()
      teardownResizeObserver()
      closePhotoPreview()
      clearCaptureReview()
      showPendingLimitModal.value = false
      await closeCamera()
      revokeThumbs()
      showEdit.value = false
    }
  }
)

watch([boardRef, boardVisible, () => props.modelValue], () => {
  nextTick(() => {
    if (props.modelValue) {
      paintBoardPreview()
      bindBoardTouch()
    } else unbindBoardTouch()
  })
})

watch(fields, () => schedulePaintBoardPreviewFromFields(), { deep: true })

watch(boardUiCycle, () =>
  nextTick(() => {
    requestAnimationFrame(() => {
      clampPosition()
      paintBoardPreview()
    })
  })
)

watch(boardVisible, () =>
  nextTick(() => {
    requestAnimationFrame(() => {
      clampPosition()
      paintBoardPreview()
    })
  })
)

onUnmounted(() => {
  clearLayoutRetryTimers()
  unbindBoardTouch()
  teardownResizeObserver()
  closePhotoPreview()
  clearCaptureReview()
  showPendingLimitModal.value = false
  closeCamera()
  revokeThumbs()
})

function boardPayload() {
  const p = activeBoardPreset.value ?? BOARD_SIZE_PRESETS[0]
  const d = boardDisplayPx.value
  return {
    templateId: 'default',
    x: boardX.value,
    y: boardY.value,
    scale: 1,
    fields: {
      projectName: fields.value.projectName,
      companyName: fields.value.companyName,
      siteName: fields.value.siteName,
      subject: fields.value.subject
    },
    rotateBoardCw90: boardRotated90.value,
    layoutWidth: d.width,
    layoutHeight: d.height,
    boardPresetId: p.id
  }
}

function makeFileName() {
  const d = new Date()
  const pad = (n) => String(n).padStart(2, '0')
  const short = Math.random().toString(36).slice(2, 8)
  return `board_${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}_${short}.jpg`
}

async function capture() {
  if (isCapturing.value || captureReviewPending.value || !frameRef.value || !videoRef.value) return
  const v = videoRef.value
  if (!v.videoWidth) {
    cameraError.value = '映像の準備ができていません'
    return
  }

  isCapturing.value = true
  cameraError.value = null
  const pulseTorch = torchMode.value === 'capture' && torchAvailable.value
  try {
    await sleep(100)
    if (pulseTorch) {
      await applyTorch(true)
      await sleep(220)
    }
    await nextTick()
    const frameEl = frameRef.value
    const br = boardVisualRef.value?.getBoundingClientRect()
    const localRect =
      frameEl && br
        ? viewportRectToFrameContentLocal(frameEl, br)
        : { left: 0, top: 0, width: 1, height: 1 }

    const composite = await compositeVideoFrameWithBoard(
      v,
      frameRef.value,
      localRect,
      boardPayload(),
      boardVisible.value
    )
    /** 黒板向き（横向き）ボタン ON → 1280×960・rotation 0 / OFF → 960×1280・rotation 270 */
    const rotationMeta = composite.exportLandscape ? 0 : 270
    const packed = await processBoardCaptureForUpload(composite.blob, { rotation: rotationMeta })

    const createdAt = new Date().toISOString()
    const fileName = makeFileName()
    captureReviewDraft.value = {
      blob: packed.mainImage,
      width: packed.width,
      height: packed.height,
      thumbnailBlob: packed.thumbnail,
      sthumbBlob: packed.sthumb,
      rotation: packed.rotation,
      isStandardAspectRatio: packed.isStandardAspectRatio,
      fileName,
      createdAt,
      board: boardPayload()
    }
    captureReviewObjectUrl.value = URL.createObjectURL(composite.portraitBlob)
    captureReviewPending.value = true
  } catch (e) {
    console.error(e)
    cameraError.value = e?.message || '撮影に失敗しました'
  } finally {
    if (pulseTorch) await applyTorch(false)
    if (torchMode.value === 'always' && torchAvailable.value) await applyTorch(true)
    isCapturing.value = false
  }
}

async function removePhoto(id) {
  await indexedDBService.deleteBoardCapturePhoto(id)
  if (thumbUrls.value[id]) {
    URL.revokeObjectURL(thumbUrls.value[id])
    delete thumbUrls.value[id]
  }
  sessionPhotos.value = sessionPhotos.value.filter((p) => p.id !== id)
}

async function finishUpload() {
  const pending = sessionPhotos.value.filter((p) => p.status === 'saved_local' || p.status === 'failed')
  if (pending.length === 0 || isUploadingBatch.value) return

  isUploadingBatch.value = true
  for (const p of pending) {
    await indexedDBService.updateBoardCapturePhoto(p.id, { status: 'uploading' })
  }
  await loadSession()

  const files = pending.map((p) => new File([p.blob], p.fileName, { type: p.mimeType || 'image/jpeg' }))

  /** アップロード API は exifDateTime を taken_at に格納する。合成 JPEG に EXIF は無いので送信時刻を渡す */
  const uploadTakenAtIso = new Date().toISOString()
  const boardCapturePreprocessed = {}
  for (const p of pending) {
    if (p.thumbnailBlob && p.sthumbBlob) {
      boardCapturePreprocessed[p.fileName] = {
        mainImage: p.blob,
        thumbnail: p.thumbnailBlob,
        sthumb: p.sthumbBlob,
        width: p.width,
        height: p.height,
        rotation: typeof p.rotation === 'number' ? p.rotation : 0,
        isStandardAspectRatio: p.isStandardAspectRatio !== false,
        exifDateTime: uploadTakenAtIso
      }
    }
  }

  const reconcile = async (uploadResults) => {
    const successNames = new Set((uploadResults.success || []).map((s) => s.original_name))
    for (const p of pending) {
      if (successNames.has(p.fileName)) {
        if (thumbUrls.value[p.id]) {
          URL.revokeObjectURL(thumbUrls.value[p.id])
          delete thumbUrls.value[p.id]
        }
        await indexedDBService.deleteBoardCapturePhoto(p.id)
      }
    }
    for (const err of uploadResults.errors || []) {
      const name = err.file?.name
      if (!name) continue
      const p = pending.find((x) => x.fileName === name)
      if (!p) continue
      const cur = await indexedDBService.getBoardCapturePhoto(p.id)
      await indexedDBService.updateBoardCapturePhoto(p.id, {
        status: 'failed',
        errorMessage: String(err.error || 'アップロード失敗'),
        uploadRetryCount: (cur?.uploadRetryCount || 0) + 1
      })
    }
    for (const p of pending) {
      const cur = await indexedDBService.getBoardCapturePhoto(p.id)
      if (cur?.status === 'uploading') {
        await indexedDBService.updateBoardCapturePhoto(p.id, {
          status: 'failed',
          errorMessage: '送信結果が取得できませんでした',
          uploadRetryCount: (cur?.uploadRetryCount || 0) + 1
        })
      }
    }
    await loadSession()
  }

  async function revertUploadingState() {
    for (const p of pending) {
      const cur = await indexedDBService.getBoardCapturePhoto(p.id)
      if (cur?.status === 'uploading') {
        await indexedDBService.updateBoardCapturePhoto(p.id, {
          status: 'saved_local',
          errorMessage: null
        })
      }
    }
    await loadSession()
  }

  try {
    const result = await props.uploadHandler(files, props.targetSlotId, {
      work_category_id: props.workCategoryId,
      work_kind: props.workKind || undefined,
      boardCapturePreprocessed:
        Object.keys(boardCapturePreprocessed).length > 0 ? boardCapturePreprocessed : undefined,
      onAfterUploadAttempt: reconcile,
      allowPartialUploadResult: true,
      allowPartialCommit: true
    })
    if (result?.aborted || result?.error) {
      await revertUploadingState()
    }
  } catch (e) {
    console.error(e)
    await revertUploadingState()
  } finally {
    isUploadingBatch.value = false
  }
}

function close() {
  emit('update:modelValue', false)
  emit('closed')
}
</script>

