<template>
  <div v-if="normalizedText" class="info-row-vertical">
    <span class="info-label">{{ label }}</span>
    <button
      type="button"
      class="info-value change-text-expand"
      :class="{ 'is-expandable': measured && overflows }"
      :aria-expanded="measured && overflows ? expanded : undefined"
      @click="onClick"
    >
      <span
        ref="bodyRef"
        class="change-text-body"
        :class="bodyClass"
      >{{ normalizedText }}</span>
    </button>
  </div>
</template>

<script setup>
import { computed, ref, watch, onMounted, onUnmounted, nextTick } from 'vue'

const props = defineProps({
  label: { type: String, required: true },
  text: { type: String, default: '' },
  /** 案件切替時に折りたたみをリセットするためのキー（例: workId + フィールド名） */
  resetKey: { type: String, default: '' }
})

const expanded = ref(false)
const bodyRef = ref(null)
/** 画面幅の1行に収まらないか（改行の有無では判定しない） */
const overflows = ref(false)
/** 初回の幅計測が終わったか */
const measured = ref(false)
let resizeObserver = null
let measureRafId = 0
let measuring = false

/** 表示用: 改行・連続空白を1つのスペースに（計測は nowrap の横スクロールで行う） */
const normalizedText = computed(() =>
  String(props.text ?? '').replace(/\s+/g, ' ').trim()
)

/** 計測中・折りたたみ時は nowrap。1行に収まる場合は折返しせず通常表示（ループ防止） */
const bodyClass = computed(() => {
  if (expanded.value) {
    return { 'is-expanded': true }
  }
  if (!measured.value || overflows.value) {
    return { 'is-collapsed': true }
  }
  return { 'is-single-line': true }
})

/** 画面上の1行に収まるか（scrollWidth vs 表示幅・nowrap 時） */
function measureOverflow() {
  const el = bodyRef.value
  if (!el || expanded.value || measuring) {
    return
  }

  measuring = true
  const prevWhiteSpace = el.style.whiteSpace
  const prevOverflow = el.style.overflow
  el.style.whiteSpace = 'nowrap'
  el.style.overflow = 'hidden'

  const nextOverflows = el.scrollWidth > el.clientWidth + 1
  const changed = nextOverflows !== overflows.value || !measured.value
  overflows.value = nextOverflows
  measured.value = true

  el.style.whiteSpace = prevWhiteSpace
  el.style.overflow = prevOverflow
  measuring = false

  return changed
}

async function scheduleMeasure() {
  await nextTick()
  measureOverflow()
}

function scheduleMeasureFromResize() {
  if (expanded.value || measuring) return
  if (measureRafId) {
    cancelAnimationFrame(measureRafId)
  }
  measureRafId = requestAnimationFrame(() => {
    measureRafId = 0
    measureOverflow()
  })
}

function resetAndMeasure() {
  expanded.value = false
  measured.value = false
  overflows.value = false
  scheduleMeasure()
}

watch(() => props.resetKey, resetAndMeasure)
watch(() => props.text, resetAndMeasure)

watch(expanded, (isExpanded) => {
  if (!isExpanded) {
    scheduleMeasure()
  }
})

function onClick() {
  if (!measured.value || !overflows.value) return
  expanded.value = !expanded.value
}

onMounted(() => {
  scheduleMeasure()
  const el = bodyRef.value
  if (typeof ResizeObserver !== 'undefined' && el) {
    resizeObserver = new ResizeObserver(() => {
      scheduleMeasureFromResize()
    })
    resizeObserver.observe(el)
    if (el.parentElement) {
      resizeObserver.observe(el.parentElement)
    }
  }
})

onUnmounted(() => {
  if (measureRafId) {
    cancelAnimationFrame(measureRafId)
    measureRafId = 0
  }
  resizeObserver?.disconnect()
  resizeObserver = null
})
</script>

<style scoped>
.info-row-vertical {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  margin-bottom: 0.75rem;
}

.info-label {
  font-weight: 500;
  color: #6b7280;
  min-width: 120px;
}

.change-text-expand {
  text-align: left;
  width: 100%;
  min-width: 0;
  border: none;
  background: transparent;
  padding: 0;
  font: inherit;
  cursor: default;
  line-height: 1.5;
}

.change-text-expand.is-expandable {
  cursor: pointer;
}

.change-text-body {
  display: block;
  min-width: 0;
  width: 100%;
}

.change-text-body.is-collapsed {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #2563eb;
}

.change-text-expand.is-expandable:hover .change-text-body.is-collapsed {
  color: #1d4ed8;
}

.change-text-body.is-single-line {
  white-space: nowrap;
  overflow: hidden;
  color: #111827;
}

.change-text-body.is-expanded {
  white-space: normal;
  word-break: break-word;
  overflow: visible;
  color: #111827;
  background: #eff6ff;
  padding: 0.375rem 0.5rem;
  border-radius: 0.375rem;
}
</style>
