// 画像リサイズユーティリティ
// 画像: 縦横維持・長い方1280マックス
// サムネイル: 縦横維持・長い方400マックス
// 小サムネイル: 縦横維持・長い方180マックス

import exifr from 'exifr'

/** メイン画像の長辺上限 */
const MAIN_MAX_LONGER = 1280
/** サムネイル(_thumb.jpg)の長辺上限 */
const THUMB_MAX_LONGER = 400
/** 小サムネイル(_sthumb.jpg)の長辺上限 */
const STHUMB_MAX_LONGER = 180

export function isHeicLikeFile(file) {
  if (!file) return false
  const mime = String(file.type || '').toLowerCase()
  const name = String(file.name || '').toLowerCase()
  return mime === 'image/heic' ||
    mime === 'image/heif' ||
    /\.(heic|heif)$/i.test(name)
}

function replaceImageExtensionWithJpg(name) {
  const raw = String(name || '').trim()
  if (!raw) return 'upload.jpg'
  return raw.replace(/\.(heic|heif)$/i, '.jpg')
}

async function convertHeicToJpegFile(file) {
  if (!isHeicLikeFile(file)) return file

  try {
    const mod = await import('heic2any')
    const heic2any = mod.default || mod
    const converted = await heic2any({
      blob: file,
      toType: 'image/jpeg',
      quality: 0.92
    })
    const jpegBlob = Array.isArray(converted) ? converted[0] : converted
    if (!(jpegBlob instanceof Blob) || jpegBlob.size === 0) {
      throw new Error('HEICのJPEG変換結果が空です')
    }
    return new File([jpegBlob], replaceImageExtensionWithJpg(file.name), { type: 'image/jpeg' })
  } catch (error) {
    console.error('[imageResize] HEIC変換エラー:', error)
    throw new Error('HEIC画像をJPEGに変換できませんでした')
  }
}

/**
 * 縦横比を維持し、長い辺が maxLonger を超える場合にリサイズ
 * @param {number} w - 幅
 * @param {number} h - 高さ
 * @param {number} maxLonger - 長い辺の最大値
 * @returns {{w: number, h: number}}
 */
function resizeByLongerSide(w, h, maxLonger) {
  const longer = Math.max(w, h)
  if (longer <= maxLonger) return { w, h }
  const ratio = maxLonger / longer
  return {
    w: Math.round(w * ratio),
    h: Math.round(h * ratio)
  }
}

/**
 * EXIF Orientationを取得
 * @param {File} file - 画像ファイル
 * @returns {Promise<number>} EXIF Orientation (1-8)
 */
async function getExifOrientation(file) {
  return new Promise((resolve) => {
    const reader = new FileReader()
    reader.onload = (e) => {
      try {
        const view = new DataView(e.target.result)
        const length = view.byteLength
        if (length < 2 || view.getUint16(0, false) !== 0xffd8) {
          resolve(1)
          return
        }
        let offset = 2
        while (offset < length) {
          if (offset + 2 > length) break
          const marker = view.getUint16(offset, false)
          offset += 2
          if (marker === 0xffe1) {
            if (offset + 2 > length) break
            const exifLength = view.getUint16(offset, false)
            offset += 2
            if (offset + 6 > length) { resolve(1); return }
            if (view.getUint32(offset, false) !== 0x45786966) { resolve(1); return }
            offset += 6
            if (offset + 2 > length) { resolve(1); return }
            const littleEndian = view.getUint16(offset, false) === 0x4949
            offset += 2
            if (offset + 2 > length) { resolve(1); return }
            if (view.getUint16(offset, littleEndian) !== 0x002a) { resolve(1); return }
            offset += 2
            if (offset + 4 > length) { resolve(1); return }
            const ifd0Offset = view.getUint32(offset, littleEndian)
            offset += ifd0Offset - 2
            if (offset < 0 || offset >= length) { resolve(1); return }
            if (offset + 2 > length) { resolve(1); return }
            const tags = view.getUint16(offset, littleEndian)
            offset += 2
            if (offset + tags * 12 > length) { resolve(1); return }
            for (let i = 0; i < tags; i++) {
              const tagOffset = offset + i * 12
              const valueOffset = tagOffset + 8
              if (tagOffset + 2 > length || valueOffset + 2 > length) continue
              const tag = view.getUint16(tagOffset, littleEndian)
              if (tag === 0x0112) {
                resolve(view.getUint16(valueOffset, littleEndian))
                return
              }
            }
            resolve(1)
            return
          } else if ((marker & 0xff00) !== 0xff00) {
            break
          } else {
            if (offset + 2 > length) break
            offset += view.getUint16(offset, false)
            if (offset >= length) break
          }
        }
        resolve(1)
      } catch (err) {
        console.warn('EXIF orientation parsing error:', err)
        resolve(1)
      }
    }
    reader.onerror = () => resolve(1)
    reader.readAsArrayBuffer(file.slice(0, 64 * 1024))
  })
}

/**
 * EXIF DateTimeOriginal を取得
 * @param {File|Blob} file - 画像ファイル
 * @returns {Promise<string|null>} "YYYY-MM-DDTHH:mm:ss" 形式、または null
 */
async function getExifDateTime(file) {
  try {
    const exif = await exifr.parse(file, { pick: ['DateTimeOriginal'] })
    const dt = exif?.DateTimeOriginal
    if (!dt || !(dt instanceof Date) || isNaN(dt.getTime())) return null
    const pad = (n, len = 2) => String(n).padStart(len, '0')
    return `${dt.getFullYear()}-${pad(dt.getMonth() + 1)}-${pad(dt.getDate())}T${pad(dt.getHours())}:${pad(dt.getMinutes())}:${pad(dt.getSeconds())}`
  } catch {
    return null
  }
}

/**
 * EXIF Orientation から回転角度を取得
 */
function getRotationFromOrientation(orientation) {
  switch (orientation) {
    case 3: return 180
    case 6: return 90
    case 8: return 270
    default: return 0
  }
}

/**
 * Image から指定長辺上限でリサイズした Blob を生成
 * @param {HTMLImageElement} img - 読み込み済み画像
 * @param {number} maxLonger - 長い辺の最大値
 * @param {number} quality - JPEG品質（0-1）
 * @returns {Promise<Blob>}
 */
function createResizedBlobFromImage(img, maxLonger, quality = 0.85) {
  const { w, h } = resizeByLongerSide(img.width, img.height, maxLonger)
  const canvas = document.createElement('canvas')
  canvas.width = w
  canvas.height = h
  canvas.getContext('2d').drawImage(img, 0, 0, w, h)
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error('Failed to create blob'))),
      'image/jpeg',
      quality
    )
  })
}

/**
 * ファイルを読み込んで Image を返す
 */
function loadImageFromFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = (e) => {
      const img = new Image()
      img.onload = () => resolve(img)
      img.onerror = () => reject(new Error('Failed to load image'))
      img.src = e.target.result
    }
    reader.onerror = () => reject(new Error('Failed to read file'))
    reader.readAsDataURL(file)
  })
}

// ---- 公開API ----

/**
 * サムネイル作成（長い辺400px）
 */
export async function createThumbnail(file, quality = 0.85) {
  if (!file?.type?.startsWith('image/')) return null
  const img = await loadImageFromFile(file)
  return createResizedBlobFromImage(img, THUMB_MAX_LONGER, quality)
}

/**
 * 画像リサイズ（長い辺1280px）
 */
export async function resizeImage(file, maxLonger = MAIN_MAX_LONGER, quality = 0.85) {
  if (!file?.type?.startsWith('image/')) return Promise.reject(new Error('Not an image'))
  const img = await loadImageFromFile(file)
  return createResizedBlobFromImage(img, maxLonger, quality)
}

/**
 * 複数画像を一括リサイズ
 */
export async function resizeImages(files, maxLonger = MAIN_MAX_LONGER, quality = 0.85, onProgress = null) {
  const result = []
  for (let i = 0; i < files.length; i++) {
    result.push(await resizeImage(files[i], maxLonger, quality))
    if (onProgress) onProgress(i + 1, files.length)
  }
  return result
}

export function isImageFile(file) {
  return file?.type?.startsWith('image/')
}

export function filterImageFiles(files) {
  return (files || []).filter(isImageFile)
}

export function formatFileSize(bytes) {
  if (bytes === 0) return '0 Bytes'
  const k = 1024
  const sizes = ['Bytes', 'KB', 'MB', 'GB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + ' ' + sizes[i]
}

export function createImagePreviewUrl(file) {
  return URL.createObjectURL(file)
}

export function revokeImagePreviewUrl(url) {
  URL.revokeObjectURL(url)
}

/**
 * アップロード用に画像を処理（メイン + サムネイル + 小サムネイル）
 * @param {File} file - 元の画像ファイル
 * @param {Object} options - オプション（mainMaxLonger, thumbMaxLonger, sthumbMaxLonger, mainQuality, thumbQuality）
 * @returns {Promise<{mainImage, thumbnail, sthumb, width, height, rotation, exifDateTime, isStandardAspectRatio}>}
 */
export async function processImageForUpload(file, options = {}) {
  const sourceFile = isHeicLikeFile(file) ? await convertHeicToJpegFile(file) : file
  const {
    mainMaxLonger = MAIN_MAX_LONGER,
    thumbMaxLonger = THUMB_MAX_LONGER,
    sthumbMaxLonger = STHUMB_MAX_LONGER,
    mainQuality = 0.92,
    thumbQuality = 0.85,
    /** true のとき EXIF を読まない（黒板合成 JPEG など） */
    skipExif = false,
    /** 指定時はこの回転を優先（0/90/180/270）。skipExif と併用想定 */
    forcedRotation = null
  } = options

  let exifDateTime = null
  let rotationFromExif = 0
  if (!skipExif && sourceFile === file) {
    const [exifOrientation, dt] = await Promise.all([getExifOrientation(sourceFile), getExifDateTime(sourceFile)])
    exifDateTime = dt
    rotationFromExif = getRotationFromOrientation(exifOrientation)
  }

  const img = await loadImageFromFile(sourceFile)
  const ow = img.width
  const oh = img.height

  // アスペクト比チェック（4:3 系か）
  const ar = ow / oh
  const tol = 0.05
  const isStandardAspectRatio =
    Math.abs(ar - 4 / 3) < tol || Math.abs(ar - 3 / 4) < tol

  let finalRotation
  if (typeof forcedRotation === 'number' && Number.isFinite(forcedRotation)) {
    finalRotation = forcedRotation
  } else {
    finalRotation = rotationFromExif
    if (Math.abs(ar - 3 / 4) < tol && rotationFromExif === 0) finalRotation = 270
  }

  const mainSize = resizeByLongerSide(ow, oh, mainMaxLonger)

  const mainCanvas = document.createElement('canvas')
  mainCanvas.width = mainSize.w
  mainCanvas.height = mainSize.h
  mainCanvas.getContext('2d').drawImage(img, 0, 0, mainSize.w, mainSize.h)

  const [mainImage, thumbnail, sthumb] = await Promise.all([
    new Promise((resolve, reject) => {
      mainCanvas.toBlob((b) => (b ? resolve(b) : reject(new Error('Failed to create blob'))), 'image/jpeg', mainQuality)
    }),
    createResizedBlobFromImage(mainCanvas, thumbMaxLonger, thumbQuality),
    createResizedBlobFromImage(mainCanvas, sthumbMaxLonger, thumbQuality)
  ])

  return {
    mainImage,
    thumbnail,
    sthumb,
    width: mainSize.w,
    height: mainSize.h,
    rotation: finalRotation,
    exifDateTime,
    isStandardAspectRatio
  }
}

/**
 * 黒板カメラの合成 JPEG を、アップロードキューと同じ形にそろえる（EXIF は読まない）
 * @param {Blob} jpegBlob
 * @param {{ rotation: number }} opts - 縦ソース: 270 / 横ソース: 0 を想定
 */
export async function processBoardCaptureForUpload(jpegBlob, opts = {}) {
  const rotation = typeof opts.rotation === 'number' && Number.isFinite(opts.rotation) ? opts.rotation : 0
  const file = new File([jpegBlob], 'board_capture.jpg', { type: 'image/jpeg' })
  const img = await loadImageFromFile(file)
  const ow = img.width
  const oh = img.height
  const ar = ow / oh
  const tol = 0.05
  const isStandardAspectRatio = Math.abs(ar - 4 / 3) < tol || Math.abs(ar - 3 / 4) < tol
  const [thumbnail, sthumb] = await Promise.all([
    createResizedBlobFromImage(img, THUMB_MAX_LONGER, 0.85),
    createResizedBlobFromImage(img, STHUMB_MAX_LONGER, 0.85)
  ])
  return {
    mainImage: jpegBlob,
    thumbnail,
    sthumb,
    width: ow,
    height: oh,
    rotation,
    exifDateTime: null,
    isStandardAspectRatio
  }
}
