<template>
  <div class="billing-template-editor-container" :class="{ 'billing-template-editor--tablet': isTablet }">
    <!-- 左側: テンプレートリスト -->
    <div class="billing-template-editor">
      <div class="editor-header">
        <h3>小口請求</h3>
      </div>

      <div v-if="loading" class="loading-state">
        <span>読み込み中...</span>
      </div>

      <div v-else-if="error" class="error-state">
        <span>{{ error }}</span>
        <button @click="loadTemplates" class="retry-btn">再読み込み</button>
      </div>

      <div v-else class="templates-list">
        <div 
          v-for="template in templates" 
          :key="template.id"
          class="template-item"
          :class="{ 
            'is-dragging': draggingId === template.id, 
            'drag-over': dragOverId === template.id,
            'is-temp': template.label === 'temp',
            'is-selected': selectedTemplate?.id === template.id
          }"
          @dragend="handleDragEnd"
          @dragover.prevent="handleDragOver($event, template)"
          @dragleave="handleDragLeave"
          @drop.prevent="handleDrop($event, template)"
        >
          <div 
            class="template-drag-handle" 
            :class="{ disabled: template.label === 'temp' }"
            :draggable="template.label !== 'temp'"
            :title="template.label === 'temp' ? '' : 'ドラッグして並べ替え'"
            @dragstart.stop="handleDragStart($event, template)"
          >
            <span class="drag-icon">≡</span>
          </div>

          <button
            class="edit-btn"
            @click="selectTemplate(template)"
            title="詳細編集"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
              <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
            </svg>
          </button>

          <textarea
            v-if="template.label !== 'temp'"
            class="template-label-input template-label-textarea"
            :value="template.label"
            rows="1"
            @input="handleTemplateLabelInput"
            @blur="handleTemplateLabelBlur(template, $event)"
            @keydown.enter.exact.prevent="$event.target.blur()"
            @keydown.enter.shift.prevent
            placeholder="テンプレート名..."
          />
          <span v-else class="template-label temp-label">{{ template.label }}</span>

          <button
            class="copy-btn"
            :class="{ 'is-copying': copyingTemplateId === template.id }"
            :disabled="copyingTemplateId !== null"
            :aria-busy="copyingTemplateId === template.id"
            @click="copyTemplate(template)"
            :title="copyingTemplateId === template.id ? 'コピー中…' : 'コピー'"
          >
            <span v-if="copyingTemplateId === template.id" class="copy-spinner" aria-hidden="true"></span>
            <template v-else>⧉</template>
          </button>
          <button
            v-if="template.label !== 'temp'"
            class="delete-btn"
            @click="deleteTemplate(template)"
            title="削除"
          >
            ✕
          </button>
          <div v-else class="delete-placeholder"></div>
        </div>

        <!-- 新規テンプレート追加 -->
        <div class="template-item new-template-item">
          <div class="template-drag-handle disabled">
            <span class="drag-icon">≡</span>
          </div>
          <div class="edit-placeholder"></div>
          <textarea
            class="template-label-input template-label-textarea new-template-input"
            v-model="newTemplateLabel"
            rows="1"
            @input="handleNewTemplateLabelInput"
            @keydown.enter.exact.prevent="addNewTemplate"
            @keydown.enter.shift.prevent
            placeholder="新規"
          />
          <button 
            class="add-template-btn"
            @click="addNewTemplate"
            :disabled="!newTemplateLabel.trim()"
            title="追加"
          >
            ＋
          </button>
        </div>

        <div v-if="templates.length === 0" class="empty-state">
          <p>請求テンプレートがありません</p>
        </div>
      </div>
    </div>

    <!-- 右側: 詳細パネル -->
    <div class="billing-detail-panel">
      <!-- 未選択時 -->
      <div v-if="!selectedTemplate" class="panel-placeholder-container">
        <p class="panel-placeholder">← テンプレートの編集ボタンをクリックして編集</p>
      </div>

      <!-- 選択時: 詳細編集 -->
      <div v-else class="panel-edit-view">

        <!-- 設定エリア（右パネルは保存ボタンで一括送信） -->
        <div class="settings-row">
          <div class="settings-row-save-and-note">
            <button
              type="button"
              class="save-button billing-detail-save-btn"
              :class="{ 'has-changes': isDetailPanelDirty && !detailPanelSaving, 'is-saving': detailPanelSaving }"
              :disabled="!isDetailPanelDirty || detailPanelSaving"
              :aria-busy="detailPanelSaving"
              :title="detailPanelSaving ? '保存中…' : '詳細の変更を保存'"
              @click="saveDetailPanel"
            >
              <span v-if="detailPanelSaving" class="billing-detail-save-spinner" aria-hidden="true"></span>
              <svg
                v-else
                xmlns="http://www.w3.org/2000/svg"
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
                <polyline points="17 21 17 13 7 13 7 21"></polyline>
                <polyline points="7 3 7 8 15 8"></polyline>
              </svg>
            </button>
            <div
              class="expandable-textarea-container"
              :class="{ expanded: isImplementationExpanded }"
            >
              <textarea
                class="expandable-textarea"
                v-model="implementationNote"
                @focus="isImplementationExpanded = true"
                @blur="handleImplementationBlur"
                placeholder="実施事項..."
                rows="1"
              ></textarea>
            </div>
          </div>
          <div class="settings-row-extra">
            <select v-model="wasteDisposal" class="waste-select" :class="{ 'placeholder': !wasteDisposal }">
              <option value="">産廃</option>
              <option value="一次保管">一次保管</option>
              <option value="処分済">処分済</option>
              <option value="なし">なし</option>
            </select>
            <label class="check-label">
              <input type="checkbox" v-model="hasPhoto" />
              <span>写真</span>
            </label>
            <label class="check-label">
              <input type="checkbox" v-model="hasDrawing" />
              <span>図面</span>
            </label>
            <label class="check-label">
              <input type="checkbox" v-model="hasPriceEvidence" />
              <span>単価根拠</span>
            </label>
            <label class="check-label">
              <input type="checkbox" v-model="hasOther" />
              <span>その他</span>
            </label>
            <button
              type="button"
              class="billing-detail-close-btn"
              title="詳細を閉じる"
              @click="closePanel"
            >
              ✕
            </button>
          </div>
        </div>

        <!-- 検索 + 区分 + プライスリスト -->
        <div class="search-filter-row">
          <button
            type="button"
            class="user-price-open-btn"
            :disabled="!selectedTemplate"
            title="ユーザー単価を追加"
            @click="openUserItemModal(null)"
          >
            ユーザー
          </button>
          <label class="exclude-material-labor-a-label">
            <input v-model="excludeMaterialLaborA" type="checkbox" />
            <span>A単価除く</span>
          </label>
          <input 
            type="text" 
            v-model="searchQuery" 
            placeholder="コード・説明で検索..."
            class="search-input"
          />
          <select v-model="selectedBigCategory" @change="handleBigCategoryChange" class="category-select" :class="{ 'placeholder': !selectedBigCategory }">
            <option value="">区分</option>
            <option v-for="cat in bigCategoryOptions" :key="cat.id" :value="cat.id">{{ cat.label }}</option>
          </select>
          <select v-model="selectedPriceListId" @change="loadPriceListItems" :disabled="priceLists.length === 0" class="pricelist-select" :class="{ 'placeholder': !selectedPriceListId }">
            <option value="">プライスリスト</option>
            <option v-for="pl in priceLists" :key="pl.id" :value="pl.id">{{ pl.label }}</option>
          </select>
        </div>

        <!-- プライスリストアイテム -->
        <div class="price-items-section">
          <div v-if="priceLoading" class="loading-state small">読み込み中...</div>
          <div v-else-if="priceError" class="error-state small">
            {{ priceError }}
            <button @click="loadPriceListItems" class="retry-btn small">再読み込み</button>
          </div>
          <template v-else>
            <div v-if="!selectedPriceListId" class="empty-state small">
              プライスリストを選択してください
            </div>
            <div v-else-if="priceListItems.length === 0" class="empty-state small">
              アイテムがありません
            </div>
            <div v-else-if="filteredItems.length === 0" class="empty-state small">
              検索結果がありません
            </div>
            <div
              v-else
              ref="priceListScrollEl"
              class="price-items-list price-items-list--virtual"
            >
              <div
                class="price-list-virtual-viewport"
                :style="{
                  height: `${priceListVirtualizer.getTotalSize()}px`,
                  position: 'relative',
                  width: '100%',
                }"
              >
                <div
                  v-for="v in priceListVirtualizer.getVirtualItems()"
                  :key="v.key"
                  :ref="priceListVirtualizer.measureElement"
                  class="price-item-virtual-wrap"
                  :data-index="v.index"
                  :style="{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    transform: `translateY(${v.start}px)`,
                  }"
                >
                  <div
                    v-if="filteredItems[v.index]"
                    class="price-item"
                    :class="{ selected: selectedPriceItemId === filteredItems[v.index].id }"
                    draggable="true"
                    @dragstart="handlePriceItemDragStart($event, filteredItems[v.index])"
                    @dragend="handlePriceItemDragEnd"
                    @dblclick.prevent="handlePriceItemDblClick(filteredItems[v.index])"
                    @click="handlePriceItemTap(filteredItems[v.index])"
                    :title="isTablet ? 'タップで選択、もう一度で追加' : 'ドラッグまたはダブルクリックで追加'"
                  >
                    <div class="price-item-row-primary">
                      <div class="price-item-code">{{ filteredItems[v.index].external_code }}</div>
                      <div
                        class="price-item-type"
                        :class="{ 'price-type--material-labor': isMaterialOrLaborHighlightPriceType(filteredItems[v.index].price_type) }"
                      >
                        {{ filteredItems[v.index].price_type || '-' }}
                      </div>
                      <div class="price-item-desc">{{ filteredItems[v.index].description }}</div>
                      <div class="price-item-add-desc" v-if="filteredItems[v.index].additional_description">
                        {{ filteredItems[v.index].additional_description }}
                      </div>
                    </div>
                    <div class="price-item-row-secondary">
                      <div class="price-item-unit">{{ filteredItems[v.index].unit || '-' }}</div>
                      <div class="price-item-note" v-if="filteredItems[v.index].note">{{ filteredItems[v.index].note }}</div>
                      <div class="price-item-price">¥{{ formatPrice(filteredItems[v.index].unit_price) }}</div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </template>
        </div>

        <!-- テンプレート内アイテム一覧 -->
        <div 
          class="template-items-section"
          @dragover.prevent="handleListDragOver"
          @dragleave="handleTemplateSectionDragLeave"
          @drop.prevent="handleListDrop"
          :class="{ 'list-drop-target': isListDropTarget }"
        >
          <div class="section-header">
            <button
              type="button"
              class="material-labor-a-judge-btn"
              :disabled="itemsLoading || !selectedPriceListId"
              title="材工A単価を算出して登録済みアイテムに追加"
              @click="runMaterialLaborAJudge"
            >
              A単価判定
            </button>
            <span class="section-title">登録済みアイテム</span>
            <span class="section-count">{{ templateItems.length }}件</span>
            <span class="section-total">合計: ¥{{ formatPrice(totalAmount) }}</span>
          </div>
          
          <div v-if="itemsLoading" class="loading-state small">読み込み中...</div>
          <div v-else class="template-items-list">
            <div 
              v-for="(item, index) in templateItems" 
              :key="item.id"
              class="template-item-row"
              :class="{ 
                'drop-target': dropTargetItemId === item.id,
                'item-dragging': draggingItemId === item.id,
                'item-drag-over': itemDragOverId === item.id,
                'item-glow-blue': glowBlueItemIds.includes(item.id),
                'item-glow-red': glowRedItemIds.includes(item.id)
              }"
              @dragover.prevent.stop="handleItemDragOver($event, item)"
              @drop.prevent.stop="handleItemDrop($event, item)"
            >
              <div class="template-item-row-primary">
                <div
                  class="item-drag-handle"
                  draggable="true"
                  title="ドラッグで並び替え"
                  @dragstart.stop="handleItemDragStart($event, item)"
                  @dragend="handleItemDragEnd"
                >
                  ≡
                </div>
                <span v-if="!isTablet" class="item-index">{{ index + 1 }}</span>
                <input
                  v-if="!item.is_user"
                  type="text"
                  class="item-code-input"
                  :value="item.external_code"
                  @input="handleCodeInput(item, $event)"
                  @blur="handleCodeBlur(item, $event.target.value)"
                  @keydown.enter="$event.target.blur()"
                  @dragover.prevent="handleCodeInputDragOver"
                  @drop.prevent.stop="handleCodeInputDrop($event, item)"
                  placeholder="コード"
                />
                <span v-else class="item-code-readonly">{{ getUserItemCodePreview(item) }}</span>
                <button
                  v-if="item.is_user"
                  type="button"
                  class="item-price-type item-price-type--user"
                  title="ユーザー単価を編集"
                  @click="openUserItemModal(item)"
                >
                  ユーザー
                </button>
                <span
                  v-else
                  class="item-price-type"
                  :class="{ 'price-type--material-labor': isMaterialOrLaborHighlightPriceType(getPriceInfo(item.external_code, 'price_type')) }"
                >
                  {{ getPriceInfo(item.external_code, 'price_type') }}
                </span>
                <span
                  class="item-description"
                  :class="{ 'item-description--stored': isStoredDescriptionFallback(item) }"
                >{{ getTemplateItemDescriptionText(item) }}</span>
                <div
                  v-if="item.is_user && !isUserItemTmSynced(item) && getTemplateItemShapeDisplayText(item)"
                  class="price-item-add-desc template-item-add-desc"
                  :class="{ 'item-field--stored-fallback': isStoredShapeFallback(item) }"
                >
                  {{ getTemplateItemShapeDisplayText(item) }}
                </div>
                <div
                  v-else-if="isRegularLikeTemplateItem(item) && getPriceInfo(item.external_code, 'additional_description')"
                  class="price-item-add-desc template-item-add-desc"
                >
                  {{ getPriceInfo(item.external_code, 'additional_description') }}
                </div>
              </div>
              <div class="template-item-row-secondary">
                <div class="quantity-control">
                  <button class="qty-btn" @click="decrementQuantity(item)">−</button>
                  <input 
                    type="text" 
                    class="item-quantity-input"
                    :value="item.quantity"
                    @input="handleQuantityInput(item, $event)"
                    @blur="handleQuantityBlur(item, $event)"
                    @keydown.enter="$event.target.blur()"
                    @keydown="preventInvalidQuantityInput"
                    placeholder="数量"
                  />
                  <button class="qty-btn" @click="incrementQuantity(item)">＋</button>
                </div>
                <span
                  class="item-unit"
                  :class="{ 'item-field--stored-fallback': isStoredUnitFallback(item) }"
                >{{ getTemplateItemUnitDisplay(item) }}</span>
                <span
                  v-if="item.is_user && !isUserItemTmSynced(item)"
                  class="item-note-readonly"
                  :class="{ 'item-field--stored-fallback': isStoredNoteFallback(item) }"
                >{{ getTemplateItemNoteDisplayText(item) }}</span>
                <textarea
                  v-else
                  class="item-note-input item-note-textarea"
                  :value="item.note"
                  rows="1"
                  :ref="(el) => el && resizeTemplateLabelTextarea(el)"
                  @input="handleItemNoteInput"
                  @blur="handleItemNoteBlur(item, $event)"
                  @keydown.enter.exact.prevent="$event.target.blur()"
                  @keydown.enter.shift.prevent
                  placeholder="備考..."
                />
                <span
                  class="item-unit-price"
                  :class="{ 'item-field--stored-fallback': isStoredUnitPriceFallback(item) }"
                >{{ getTemplateItemUnitPriceDisplay(item) }}</span>
                <button class="item-delete-btn" @click="deleteTemplateItem(item, index)">✕</button>
              </div>
            </div>
            <div v-if="templateItems.length === 0" class="empty-state small drop-hint">
              アイテムがありません<br>
              <small>プライスリストからドラッグまたはダブルクリックで追加</small>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <BillingTemplateUserItemModal
    :show="userItemModalOpen"
    :is-edit="!!userItemModalEditItem"
    :is-reregister="userItemModalIsReregister"
    :draft="userItemModalDraft"
    :external-code="userItemModalExternalCode"
    @request-close="handleUserItemModalRequestClose"
    @confirm="handleUserItemModalConfirm"
    @reregister="handleUserItemModalReregister"
  />
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue'
import { useVirtualizer, measureElement } from '@tanstack/vue-virtual'
import { supabaseService } from '../services/supabase'
import { indexedDBService } from '../utils/indexedDB'
import { comparePriceListsByFiscalThenRevision } from '../utils/pickNewestPriceList'
import BillingTemplateUserItemModal from './BillingTemplateUserItemModal.vue'
import {
  shouldConfirmSaveForMaterialLabor,
  shouldConfirmBeforeMaterialLaborJudge,
  computeMaterialLaborAJudge,
  planMaterialLaborApply,
  buildMaterialLaborPreviewLines,
  isMaterialLaborAPriceType,
  isMaterialOrLaborHighlightPriceType
} from '../utils/materialLaborAJudge.js'
import { useDialog } from '../composables/useDialog'
import { useViewport } from '../composables/useViewport'

const dialog = useDialog()
const { isTablet } = useViewport({ mobileMax: 900, tabletMax: 1500 })

const selectedPriceItemId = ref(null)

const templates = ref([])
const loading = ref(true)
const error = ref(null)
const draggingId = ref(null)
const dragOverId = ref(null)
const copyingTemplateId = ref(null)

function resizeTemplateLabelTextarea(el) {
  if (!el) return
  el.style.height = 'auto'
  el.style.height = `${el.scrollHeight}px`
}

function handleTemplateLabelInput(event) {
  resizeTemplateLabelTextarea(event.target)
}

function handleNewTemplateLabelInput(event) {
  resizeTemplateLabelTextarea(event.target)
}

function fitAllAutoHeightTextareas() {
  const resizeAll = () => {
    document
      .querySelectorAll('.billing-template-editor .template-label-textarea, .template-item-row .item-note-textarea')
      .forEach((el) => resizeTemplateLabelTextarea(el))
  }
  nextTick(() => {
    resizeAll()
    nextTick(resizeAll)
  })
}

function handleItemNoteInput(event) {
  resizeTemplateLabelTextarea(event.target)
}

function handleItemNoteBlur(item, event) {
  resizeTemplateLabelTextarea(event.target)
  localApplyItemField(item, 'note', event.target.value)
}

async function handleTemplateLabelBlur(template, event) {
  resizeTemplateLabelTextarea(event.target)
  await saveTemplateLabelDirect(template, event.target.value)
}

// 選択中のテンプレート
const selectedTemplate = ref(null)

// 新規テンプレート追加
const newTemplateLabel = ref('')

// 設定項目
const implementationNote = ref('')
const isImplementationExpanded = ref(false)
const wasteDisposal = ref('')
const hasPhoto = ref(false)
const hasDrawing = ref(false)
const hasPriceEvidence = ref(false)
const hasOther = ref(false)

// プライスリスト関連（小口は年度で絞らず kind=small の一覧を取得）
const priceLists = ref([])
const selectedPriceListId = ref('')
const priceListItems = ref([])
const priceLoading = ref(false)
const priceError = ref(null)
const searchQuery = ref('')
const excludeMaterialLaborA = ref(false)

// カテゴリーフィルター
const selectedBigCategory = ref('')
const selectedSmallCategory = ref('')

/** master_price_categories（IndexedDB）— price_list_items にラベルが無い場合の付与用 */
const allCategories = ref([])

// テンプレートアイテム関連
const templateItems = ref([])
const itemsLoading = ref(false)

/** 右パネル（詳細）の未保存検知用スナップショット */
const detailPanelBaseline = ref(null)
/** 最後に同期したサーバー明細（TM 反映などの競合検知用） */
const detailPanelServerItemsRevision = ref(null)
const deletedPersistedItemIds = ref([])
const detailPanelSaving = ref(false)

const userItemModalOpen = ref(false)
const userItemModalEditItem = ref(null)
const userItemModalDraft = ref(null)
const userItemModalReregisterSourceItem = ref(null)

const userItemModalIsReregister = computed(() => !!userItemModalReregisterSourceItem.value)

const userItemModalExternalCode = computed(() => {
  if (userItemModalReregisterSourceItem.value) return ''
  const item = userItemModalEditItem.value
  if (!item) return ''
  return String(item.external_code ?? '').trim()
})

// プライスリストからのドラッグ&ドロップ
const draggingPriceItem = ref(null)
const dropTargetItemId = ref(null)
const isListDropTarget = ref(false)

// アイテム並び替え用
const draggingItemId = ref(null)
const itemDragOverId = ref(null)

/** A単価判定後の行ハイライト（id 配列） */
const glowBlueItemIds = ref([])
const glowRedItemIds = ref([])
const GLOW_ANIMATION_MS = 1600
let glowBlueClearTimer = null
let glowRedClearTimer = null

// プライスリストアイテムをexternal_codeでマップ（高速参照用）
const priceItemsMap = computed(() => {
  const map = {}
  priceListItems.value.forEach(item => {
    map[item.external_code] = item
  })
  return map
})

// 合計金額
const totalAmount = computed(() => {
  return templateItems.value.reduce((sum, item) => {
    const unitPrice = getTemplateItemUnitPrice(item) ?? 0
    const quantity = item.quantity || 0
    return sum + (unitPrice * quantity)
  }, 0)
})

// 区分（big category）のオプション - price_list_itemsから抽出
const bigCategoryOptions = computed(() => {
  const categoryMap = new Map()
  priceListItems.value.forEach(item => {
    if (item.price_big_category_id && item.price_big_category_label) {
      categoryMap.set(item.price_big_category_id, item.price_big_category_label)
    }
  })
  return Array.from(categoryMap, ([id, label]) => ({ id, label }))
    .sort((a, b) => a.label.localeCompare(b.label, 'ja'))
})

// 大分類（small category）のオプション - 選択された区分に連動
const smallCategoryOptions = computed(() => {
  const categoryMap = new Map()
  let items = priceListItems.value
  
  // 区分が選択されていればフィルタリング
  if (selectedBigCategory.value) {
    items = items.filter(item => item.price_big_category_id == selectedBigCategory.value)
  }
  
  items.forEach(item => {
    if (item.price_small_category_id && item.price_small_category_label) {
      categoryMap.set(item.price_small_category_id, item.price_small_category_label)
    }
  })
  return Array.from(categoryMap, ([id, label]) => ({ id, label }))
    .sort((a, b) => a.label.localeCompare(b.label, 'ja'))
})

// フィルタリングされたアイテム
const filteredItems = computed(() => {
  let items = priceListItems.value

  if (excludeMaterialLaborA.value) {
    items = items.filter((item) => !isMaterialLaborAPriceType(item.price_type))
  }
  
  // 区分フィルター
  if (selectedBigCategory.value) {
    items = items.filter(item => item.price_big_category_id == selectedBigCategory.value)
  }
  
  // 大分類フィルター
  if (selectedSmallCategory.value) {
    items = items.filter(item => item.price_small_category_id == selectedSmallCategory.value)
  }
  
  // テキスト検索（複数条件対応：全角・半角スペース区切り）
  if (searchQuery.value.trim()) {
    // 全角・半角スペースで分割してトリム
    const keywords = searchQuery.value
      .split(/[\s　]+/)
      .map(k => k.trim().toLowerCase())
      .filter(k => k.length > 0)
    
    if (keywords.length > 0) {
      items = items.filter(item => {
        // アイテムの検索対象テキストを結合
        const searchText = [
          item.external_code || '',
          item.description || '',
          item.additional_description || '',
          item.note || ''
        ].join(' ').toLowerCase()
        
        // すべてのキーワードが含まれているかチェック（AND条件）
        return keywords.every(keyword => searchText.includes(keyword))
      })
    }
  }
  
  return items
})

const priceListScrollEl = ref(null)

const priceListVirtualizer = useVirtualizer(
  computed(() => ({
    count: filteredItems.value.length,
    getScrollElement: () => priceListScrollEl.value,
