function normalizeQty(q) {
  if (q === '' || q == null || Number.isNaN(Number(q))) return null
  const n = Number(q)
  return Number.isFinite(n) ? n : null
}

function roundTemplateQuantity(value) {
  const n = Number(value)
  if (!Number.isFinite(n)) return null
  const abs = Math.abs(n)
  if (abs < 1) return Math.round((n + Number.EPSILON) * 100) / 100
  if (abs < 100) return Math.round((n + Number.EPSILON) * 10) / 10
  return Math.round(n)
}

function normalizeUnitForSave(value) {
  if (value == null) return null
  const trimmed = String(value).trim()
  return trimmed === '' ? null : trimmed
}

function normalizeUnitPriceForSave(value) {
  if (value == null || value === '') return null
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

function normalizeUserItemForSave(ui) {
  if (!ui) {
    return {
      description: '',
      price_type: null,
      evidence: null,
      unit: null,
      additional_description: null,
      note: null,
      has_expenses: null,
      unit_price: null
    }
  }
  return {
    description: (ui.description ?? '').trim() || null,
    price_type: normalizeUnitForSave(ui.price_type),
    evidence: ui.evidence?.trim() || null,
    unit: normalizeUnitForSave(ui.unit),
    additional_description: (ui.additional_description ?? '').trim() || null,
    note: (ui.note ?? '').trim() || null,
    has_expenses: typeof ui.has_expenses === 'boolean' ? ui.has_expenses : null,
    unit_price: normalizeUnitPriceForSave(ui.unit_price)
  }
}

function createEmptyUserItem() {
  return {
    description: '',
    price_type: '',
    evidence: '',
    unit: '',
    additional_description: '',
    note: '',
    has_expenses: null,
    unit_price: null
  }
}

function isUserItemTmSynced(item) {
  if (!item?.is_user) return false
  const code = String(item.external_code ?? '').trim()
  if (!code) return false
  return !/^\d+U$/i.test(code)
}

/** NU採番対象（TM反映済みユーザー単価は除外） */
function isNuEligibleUserItem(item) {
  return !!item?.is_user && !isUserItemTmSynced(item)
}

/** TM 反映済みユーザー行は通常行と同型の一覧表示 */
function isRegularLikeTemplateItem(item) {
  return !item?.is_user || isUserItemTmSynced(item)
}

function buildServerItemsRevision(items) {
  return (items || [])
    .filter((it) => it?.id && !String(it.id).startsWith('local-'))
    .map((it) => ({
      id: String(it.id),
      external_code: it.external_code ?? null,
      note: it.note ?? null,
      description: (it.description ?? '').trim() || null,
      unit: it.unit ?? null,
      unit_price: it.unit_price ?? null,
      quantity: normalizeQty(it.quantity),
      sort_order: it.sort_order ?? null,
      is_user: !!it.is_user
    }))
    .sort((a, b) => a.id.localeCompare(b.id))
}

function setDetailPanelServerItemsRevision(items) {
  detailPanelServerItemsRevision.value = buildServerItemsRevision(items)
}

function serverItemsRevisionFingerprint(revision) {
  return JSON.stringify(revision ?? [])
}

async function handleServerItemsRevisionConflict() {
  const reload = await dialog.confirm(
    'サーバー側で明細が更新されています（Tampermonkey 反映など）。\n' +
      'このまま保存すると反映内容を上書きしてしまいます。\n\n' +
      '未保存の編集を破棄して再読み込みしますか？',
    { title: '保存できません' }
  )
  if (!reload) return false
  clearUserItemModalState()
  await loadTemplateItems()
  if (selectedTemplate.value) {
    const t = templates.value.find((x) => x.id === selectedTemplate.value.id)
    if (t) {
      implementationNote.value = t.execution_detail || ''
      wasteDisposal.value = t.industrial_waste || ''
      hasPhoto.value = !!t.has_photo
      hasDrawing.value = !!t.has_zumen
      hasPriceEvidence.value = !!t.has_evidence
      hasOther.value = !!t.has_etc
    }
    detailPanelBaseline.value = snapshotCurrentDetail()
  }
  return true
}

async function assertServerItemsRevisionCurrent() {
  if (!selectedTemplate.value) return true
  const expectedFp = serverItemsRevisionFingerprint(detailPanelServerItemsRevision.value)
  if (expectedFp === '[]' && !templateItems.value.some((it) => it?.id && !String(it.id).startsWith('local-'))) {
    return true
  }
  try {
    const serverItems = await supabaseService.getBillingTemplateItems(selectedTemplate.value.id)
    const currentFp = serverItemsRevisionFingerprint(buildServerItemsRevision(serverItems))
    if (currentFp === expectedFp) return true
    return await handleServerItemsRevisionConflict()
  } catch (err) {
    console.error('assertServerItemsRevisionCurrent:', err)
    await dialog.alert('サーバーとの同期確認に失敗しました。', { title: 'エラー' })
    return false
  }
}

function mapTemplateItemFieldsForSnapshot(item) {
  const persist = isRegularLikeTemplateItem(item)
  return {
    id: item.id,
    external_code: persist ? (item.external_code || null) : null,
    note: persist ? (item.note ?? '') : null,
    quantity: normalizeQty(item.quantity),
    description: persist ? ((item.description ?? '').trim() || null) : null,
    unit: persist ? normalizeUnitForSave(item.unit) : null,
    unit_price: persist ? normalizeUnitPriceForSave(item.unit_price) : null,
    is_user: !!item.is_user,
    user_item: item.is_user ? normalizeUserItemForSave(item.user_item) : undefined
  }
}

function snapshotCurrentDetail() {
  const tid = selectedTemplate.value?.id
  if (!tid) return null
  return {
    templateId: tid,
    execution_detail: (implementationNote.value || '').trim() || null,
    industrial_waste: wasteDisposal.value || null,
    has_photo: !!hasPhoto.value,
    has_zumen: !!hasDrawing.value,
    has_evidence: !!hasPriceEvidence.value,
    has_etc: !!hasOther.value,
    items: templateItems.value.map(mapTemplateItemFieldsForSnapshot)
  }
}

function getTemplateItemsSavePayload(items = templateItems.value) {
  return items.map((item) => {
    const persist = isRegularLikeTemplateItem(item)
    return {
      external_code: persist ? (item.external_code || null) : null,
      note: persist ? (item.note || '') : null,
      quantity: normalizeQty(item.quantity),
      description: persist ? ((item.description ?? '').trim() || null) : null,
      unit: persist ? normalizeUnitForSave(item.unit) : null,
      unit_price: persist ? normalizeUnitPriceForSave(item.unit_price) : null,
      is_user: !!item.is_user,
      user_item: item.is_user ? normalizeUserItemForSave(item.user_item) : undefined
    }
  })
}

const isDetailPanelDirty = computed(() => {
  if (!selectedTemplate.value || !detailPanelBaseline.value) return false
  return JSON.stringify(snapshotCurrentDetail()) !== JSON.stringify(detailPanelBaseline.value)
})

