// 新規テンプレート追加
async function addNewTemplate() {
  const label = newTemplateLabel.value.trim()
  if (!label) return
  
  // "temp"は予約名
  if (label.toLowerCase() === 'temp') {
    await dialog.alert('「temp」はシステム予約名のため使用できません', { title: 'エラー' })
    return
  }
  
  // 同名チェック
  const exists = templates.value.some(t => t.label === label)
  if (exists) {
    await dialog.alert('同じ名前のテンプレートが既に存在します', { title: 'エラー' })
    return
  }
  
  try {
    const newTemplate = await supabaseService.createEmptyBillingTemplate(label)
    templates.value.push(newTemplate)
    newTemplateLabel.value = ''
    fitAllAutoHeightTextareas()
  } catch (err) {
    console.error('Failed to create template:', err)
    await dialog.alert('テンプレートの作成に失敗しました', { title: 'エラー' })
  }
}

async function copyTemplate(template) {
  if (!template) return
  if (copyingTemplateId.value !== null) return

  const copiedLabel = `(コピー)${template.label}`
  if (copiedLabel.toLowerCase() === 'temp') {
    await dialog.alert('「temp」はシステム予約名のため使用できません', { title: 'エラー' })
    return
  }
  if (templates.value.some(t => t.label === copiedLabel)) {
    await dialog.alert('同じ名前のテンプレートが既に存在します', { title: 'エラー' })
    return
  }

  let createdTemplate = null
  copyingTemplateId.value = template.id
  try {
    const sourceItems = await supabaseService.getBillingTemplateItems(template.id)
    createdTemplate = await supabaseService.createEmptyBillingTemplate(copiedLabel)

    const templatePatch = {
      execution_detail: template.execution_detail || null,
      industrial_waste: template.industrial_waste || null,
      has_photo: !!template.has_photo,
      has_zumen: !!template.has_zumen,
      has_evidence: !!template.has_evidence,
      has_etc: !!template.has_etc
    }
    await supabaseService.saveBillingTemplateDetail(
      createdTemplate.id,
      templatePatch,
      getTemplateItemsSavePayload(sourceItems || [])
    )

    templates.value.push({
      ...createdTemplate,
      ...templatePatch,
      label: copiedLabel
    })
    fitAllAutoHeightTextareas()
  } catch (err) {
    console.error('Failed to copy template:', err)
    if (createdTemplate?.id) {
      try {
        await supabaseService.deleteBillingTemplate(createdTemplate.id)
      } catch (cleanupErr) {
        console.warn('Failed to cleanup copied template:', cleanupErr)
      }
    }
    await dialog.alert('テンプレートのコピーに失敗しました', { title: 'エラー' })
  } finally {
    copyingTemplateId.value = null
  }
}

function clearUserItemModalState() {
  userItemModalOpen.value = false
  userItemModalEditItem.value = null
  userItemModalDraft.value = null
  userItemModalReregisterSourceItem.value = null
}

function cloneUserItemDraftFromItem(item) {
