function getTemplateItemNoteDisplayText(item) {
  const text = getTemplateItemNoteDisplay(item)
  if (!text) return '—'
  if (isStoredNoteFallback(item)) return `（${text}）`
  return text
}

// プライスリストからコードに対応する情報を取得
function getPriceListRowForCode(code) {
  if (!code) return null
  const norm = normalizeCode(code)
  return priceItemsMap.value[norm] || priceItemsMap.value[code] || null
}

function isStoredDescriptionFallback(item) {
  if (!isRegularLikeTemplateItem(item)) {
    if ((item.description ?? '').trim()) return false
    return !!(item.user_item?.description ?? '').trim()
  }
  const row = getPriceListRowForCode(item.external_code)
  if (row) return false
  return !!(item.description ?? '').trim()
}

function getTemplateItemDescriptionText(item) {
  if (!isRegularLikeTemplateItem(item)) {
    const name = getUserItemResolvedField(item, 'description')
    if (name) {
      const text = String(name).trim()
      if (isStoredDescriptionFallback(item)) return `（${text}）`
      return text
    }
    return '-'
  }
  const row = getPriceListRowForCode(item.external_code)
  if (row) {
    const plDesc = (row.description ?? '').trim()
    return plDesc || '-'
  }
  const stored = (item.description ?? '').trim()
  if (stored) return `（${stored}）`
  return '-'
}

function isStoredShapeFallback(item) {
  if (isRegularLikeTemplateItem(item)) return false
  return !!(item.user_item?.additional_description ?? '').trim()
}

function getTemplateItemShapeDisplayText(item) {
  if (isRegularLikeTemplateItem(item)) return ''
  const text = getUserItemResolvedField(item, 'additional_description')
  if (!text) return ''
  const trimmed = String(text).trim()
  if (isStoredShapeFallback(item)) return `（${trimmed}）`
  return trimmed
}

function getUserItemResolvedField(item, field) {
  if (!item.is_user) return null
  const onItem = item[field]
  if (onItem != null && onItem !== '') return onItem
  const fromUser = item.user_item?.[field]
  if (fromUser != null && fromUser !== '') return fromUser
  return null
}

function getUserItemCodePreview(item) {
  if (!item.is_user) return item.external_code || '-'
  if (isUserItemTmSynced(item)) return item.external_code || '-'
  if (item.external_code && isUserExternalCodeNuFormat(item.external_code)) {
    return item.external_code
  }
  let n = 0
  for (const it of templateItems.value) {
    if (!isNuEligibleUserItem(it)) continue
    n += 1
    if (it.id === item.id) return `${n}U`
  }
  return '-'
}

function isPersistedTemplateItem(item) {
  return !!(item?.id && !String(item.id).startsWith('local-'))
}

function isUserExternalCodeNuFormat(code) {
  return /^\d+U$/i.test(String(code ?? '').trim())
}

function needsUserExternalCodeChoice(item) {
  return !!item?.is_user && !isUserExternalCodeNuFormat(item.external_code)
}

function buildAppendItemPreviewLine(item) {
  const code = item.is_user ? getUserItemCodePreview(item) : (item.external_code || '-')
  const description = getTemplateItemDescriptionText(item)
  const quantity = item.quantity != null && item.quantity !== '' ? item.quantity : null
  const priceType = item.is_user
    ? 'ユーザー'
    : (getPriceInfo(item.external_code, 'price_type') || '-')
  return { code, priceType, description, quantity }
}

function buildAppendItemConfirmOptions(template, item) {
  const options = {
    title: '確認',
    message: `「${template.label}」\nに以下のアイテムを登録しますか？`,
    bodyKind: 'materialLaborPreview',
    preview: {
      items: [buildAppendItemPreviewLine(item)]
    }
  }

  if (needsUserExternalCodeChoice(item)) {
    const sourceCode = String(item.external_code ?? '').trim() || '-'
    options.choiceOptions = [
      { value: 'copy', label: `元のコードをコピー（${sourceCode}）` },
      { value: 'assign_nu', label: '新規ユーザー単価登録' }
    ]
    options.defaultChoice = 'assign_nu'
    options.preview.userExternalCodeChoice = { sourceCode }
  }

  return options
}

function getTemplateItemNoteDisplay(item) {
  if (isRegularLikeTemplateItem(item)) return item.note ?? ''
  return getUserItemResolvedField(item, 'note') ?? ''
}

function isStoredNoteFallback(item) {
  if (isRegularLikeTemplateItem(item)) return false
  if (item.note != null && String(item.note).trim() !== '') return false
  return !!(item.user_item?.note ?? '').trim()
}

function isStoredUnitFallback(item) {
  if (!isRegularLikeTemplateItem(item)) {
    if (item.unit != null && String(item.unit).trim() !== '') return false
    return !!(item.user_item?.unit ?? '').trim()
  }
  const row = getPriceListRowForCode(item.external_code)
  if (row?.unit) return false
  return !!(item.unit ?? '').trim()
}

function isStoredUnitPriceFallback(item) {
  if (!isRegularLikeTemplateItem(item)) {
    if (item.unit_price != null && item.unit_price !== '') return false
    return item.user_item?.unit_price != null && item.user_item?.unit_price !== ''
  }
  const row = getPriceListRowForCode(item.external_code)
  if (row?.unit_price != null && row.unit_price !== '') return false
  return item.unit_price != null && item.unit_price !== ''
}

function getTemplateItemUnit(item) {
  if (!isRegularLikeTemplateItem(item)) {
    const v = getUserItemResolvedField(item, 'unit')
    return v || '-'
  }
  const row = getPriceListRowForCode(item.external_code)
  if (row?.unit) return row.unit
  const stored = (item.unit ?? '').trim()
  return stored || '-'
}

function getTemplateItemUnitDisplay(item) {
  const raw = getTemplateItemUnit(item)
  if (raw === '-') return '-'
  if (isStoredUnitFallback(item)) return `（${raw}）`
  return raw
}

function getTemplateItemUnitPrice(item) {
  if (!isRegularLikeTemplateItem(item)) {
    return getUserItemResolvedField(item, 'unit_price')
  }
  const row = getPriceListRowForCode(item.external_code)
  if (row?.unit_price != null && row.unit_price !== '') {
    return row.unit_price
  }
  return item.unit_price ?? null
}

function getTemplateItemUnitPriceDisplay(item) {
  const price = getTemplateItemUnitPrice(item)
  const formatted = formatPriceDisplay(price)
  if (formatted === '-') return '-'
  if (isStoredUnitPriceFallback(item)) return `（${formatted}）`
  return formatted
}

function getPriceInfo(code, field) {
  const empty = field === 'additional_description' ? '' : '-'
  if (!code) return empty
  const norm = normalizeCode(code)
  const row = priceItemsMap.value[norm] || priceItemsMap.value[code]
  if (!row) return empty
  const v = row[field]
  if (v == null || v === '') return empty
  return v
}

function buildNormalizedPriceMap() {
  const map = {}
  for (const item of priceListItems.value) {
    const norm = normalizeCode(item.external_code)
    if (norm) map[norm] = item
  }
  return map
}

function triggerItemGlowBlue(ids) {
  if (!ids?.length) return
  const merged = new Set(glowBlueItemIds.value)
  for (const id of ids) merged.add(id)
  glowBlueItemIds.value = [...merged]
  if (glowBlueClearTimer) clearTimeout(glowBlueClearTimer)
  glowBlueClearTimer = window.setTimeout(() => {
    glowBlueItemIds.value = []
    glowBlueClearTimer = null
  }, GLOW_ANIMATION_MS)
}

function triggerItemGlowRed(ids) {
  if (!ids?.length) return
  const merged = new Set(glowRedItemIds.value)
  for (const id of ids) merged.add(id)
  glowRedItemIds.value = [...merged]
  if (glowRedClearTimer) clearTimeout(glowRedClearTimer)
  glowRedClearTimer = window.setTimeout(() => {
    glowRedItemIds.value = []
    glowRedClearTimer = null
  }, GLOW_ANIMATION_MS)
}

function triggerMaterialLaborGlow(blueIds, redIds) {
  triggerItemGlowBlue(blueIds)
  triggerItemGlowRed(redIds)
}

function applyMaterialLaborPlan(plan, result) {
  const source = result.best.sourceItem
  const sourceIdx = templateItems.value.findIndex((i) => i.id === source.id)
  if (sourceIdx < 0) return

  const newItem = {
    id: `local-${crypto.randomUUID()}`,
    _isNew: true,
    external_code: plan.code2,
    note: source.note || result.best.priceRow2.note || '',
    quantity: plan.newQuantity,
    description: null
  }

  const redIds = []
  if (plan.removeSource) {
    const src = templateItems.value[sourceIdx]
    if (!src._isNew) deletedPersistedItemIds.value.push(src.id)
    templateItems.value.splice(sourceIdx, 1)
  } else {
    templateItems.value[sourceIdx].quantity = plan.sourceQuantityAfter
    redIds.push(source.id)
  }

  templateItems.value.push(newItem)
  triggerMaterialLaborGlow([newItem.id], redIds)
  fitAllAutoHeightTextareas()
}

async function runMaterialLaborAJudge() {
  if (!selectedTemplate.value) return
  if (!selectedPriceListId.value || priceListItems.value.length === 0) {
    await dialog.alert('プライスリストを選択してください', { title: 'お知らせ' })
    return
  }

  if (shouldConfirmBeforeMaterialLaborJudge(templateItems.value)) {
    const ok = await dialog.confirm(
      'A単価または労務単価が登録されています\nA単価を算出しますか？',
      { title: '確認' }
    )
    if (!ok) return
  }

  const priceMap = buildNormalizedPriceMap()
  const result = computeMaterialLaborAJudge(
    templateItems.value.filter((i) => !i.is_user),
    priceMap
  )
  if (!result.ok) {
    if (result.reason === 'no_price_change' && result.best) {
      const plan = planMaterialLaborApply(result.best, roundTemplateQuantity)
      await dialog.alert('※金額に変更がないため変換しません', {
        title: '中断',
        bodyKind: 'materialLaborPreview',
        messageClass: 'app-dialog-message--no-price-change',
        preview: buildMaterialLaborPreviewLines(result.best, plan, priceMap)
      })
      return
    }
    await dialog.alert('該当する単価がありません', { title: 'お知らせ' })
    return
  }

  const plan = planMaterialLaborApply(result.best, roundTemplateQuantity)
  const ok = await dialog.confirm('変換しますか？', {
    title: '確認',
    bodyKind: 'materialLaborPreview',
    preview: buildMaterialLaborPreviewLines(result.best, plan, priceMap)
  })
  if (!ok) return

  applyMaterialLaborPlan(plan, result)
}

function formatPriceDisplay(price) {
  if (price == null || price === '' || price === '-') return '-'
  return '¥' + formatPrice(price)
}

// 全角→半角、小文字→大文字変換、半角英大文字と半角数字以外を除去
function normalizeCode(value) {
  if (!value) return ''
  // 全角英字を半角に変換
  let normalized = value.replace(/[Ａ-Ｚａ-ｚ]/g, (s) => {
    return String.fromCharCode(s.charCodeAt(0) - 0xFEE0)
  })
  // 全角数字を半角に変換
  normalized = normalized.replace(/[０-９]/g, (s) => {
    return String.fromCharCode(s.charCodeAt(0) - 0xFEE0)
  })
  // 小文字を大文字に変換
  normalized = normalized.toUpperCase()
  // 半角英大文字と半角数字以外を除去
  normalized = normalized.replace(/[^A-Z0-9]/g, '')
  return normalized
}

