    const idSet = new Set(priceLists.value.map((p) => String(p.id)))
    const cur = String(selectedPriceListId.value ?? '')
    const needPick = priceLists.value.length > 0 && (!cur || !idSet.has(cur))

    if (priceLists.value.length === 0) {
      selectedPriceListId.value = ''
