    priceListItems.value = []
    selectedPriceItemId.value = null
    return
  }

  // カテゴリマスタが未取得のとき（静的データより後に開いた場合など）
  if (!allCategories.value.length) {
    await loadCategories()
  }

  // プライスリスト切替時のみフィルタをクリア（区分・大分類の選択肢は items から再計算）
  selectedBigCategory.value = ''
  selectedSmallCategory.value = ''
  selectedPriceItemId.value = null

  priceLoading.value = true
  priceError.value = null
  try {
    const raw = await supabaseService.getPriceListItems(selectedPriceListId.value)
    const list = raw || []
    // IndexedDB の行にラベル列が無い場合があるため、見積グリッドと同様にマスタで付与
    priceListItems.value = list.map((item) => {
      const bigCategory = allCategories.value.find((c) => c.id == item.price_big_category_id)
      const smallCategory = allCategories.value.find((c) => c.id == item.price_small_category_id)
