// コード入力時のリアルタイム変換
function handleCodeInput(item, event) {
  const normalized = normalizeCode(event.target.value)
  event.target.value = normalized
  item.external_code = normalized
}

function handleCodeBlur(item, value) {
  const normalized = normalizeCode(value) || null
  const prev = item.external_code ?? null
  if (normalized === prev) return
  item.external_code = normalized
  item.description = null
  item.unit = null
  item.unit_price = null
}

function localApplyItemField(item, field, rawValue) {
  if (field === 'quantity') {
    const value =
      rawValue === '' || rawValue == null ? null : parseFloat(rawValue)
    const next = Number.isNaN(value) || value == null ? null : roundTemplateQuantity(value)
    if (normalizeQty(item.quantity) === normalizeQty(next)) return
    item.quantity = next
    return
  }
  if (item[field] === rawValue) return
  item[field] = rawValue
}

// 数量入力時のキー入力制限（半角数字と小数点のみ許可）
function preventInvalidQuantityInput(event) {
  const key = event.key
  const currentValue = event.target.value
  
  // 許可するキー: 数字、小数点、バックスペース、Delete、Tab、矢印キー、Enter
  const allowedKeys = ['Backspace', 'Delete', 'Tab', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Enter', 'Home', 'End']
  
  if (allowedKeys.includes(key)) {
    return // 許可
  }
  
  // 数字キー（0-9）は許可
  if (/^[0-9]$/.test(key)) {
    return // 許可
  }
  
  // 小数点は1つまで許可
  if (key === '.' && !currentValue.includes('.')) {
    return // 許可
  }
  
  // それ以外は拒否
  event.preventDefault()
}

// 数量入力（半角数字と小数点のみ許可）
function handleQuantityInput(item, event) {
  let value = event.target.value
  // 全角数字を半角に変換
  value = value.replace(/[０-９]/g, (s) => String.fromCharCode(s.charCodeAt(0) - 0xFEE0))
  // 半角数字と小数点以外を除去
  value = value.replace(/[^0-9.]/g, '')
  // 小数点が複数ある場合は最初の1つだけ残す
  const parts = value.split('.')
  if (parts.length > 2) {
    value = parts[0] + '.' + parts.slice(1).join('')
  }
  event.target.value = value
  item.quantity = value ? parseFloat(value) : null
}

function handleQuantityBlur(item, event) {
  localApplyItemField(item, 'quantity', event.target.value)
  event.target.value = item.quantity ?? ''
}

function incrementQuantity(item) {
  const newQty = (item.quantity || 0) + 1
  item.quantity = newQty
}

function decrementQuantity(item) {
  const newQty = Math.max(0, (item.quantity || 0) - 1)
  item.quantity = newQty
}

function deleteTemplateItem(item, index) {
  if (item._isNew) {
    templateItems.value.splice(index, 1)
    return
  }
  deletedPersistedItemIds.value.push(item.id)
  templateItems.value.splice(index, 1)
}

// プライスリストアイテムのドラッグ
function handlePriceItemDragStart(event, item) {
  draggingPriceItem.value = item
  event.dataTransfer.effectAllowed = 'copy'
  event.dataTransfer.setData('text/plain', JSON.stringify({
    type: 'price-item',
    external_code: item.external_code,
    note: item.note
  }))
}

function handlePriceItemDragEnd() {
  draggingPriceItem.value = null
  dropTargetItemId.value = null
  isListDropTarget.value = false
}

/** プライス行ドロップ用（ドラッグ中 ref または dataTransfer の JSON） */
function getPriceItemPayloadForDrop(event) {
  if (draggingPriceItem.value) return draggingPriceItem.value
  const raw = event.dataTransfer?.getData?.('text/plain')
  if (!raw) return null
  try {
    const d = JSON.parse(raw)
    if (d?.type === 'price-item' && d.external_code != null && String(d.external_code).trim() !== '') {
      return {
        external_code: String(d.external_code),
        note: d.note || ''
      }
    }
  } catch {
    return null
  }
  return null
}

function applyPriceItemToTemplateItem(targetItem, priceRow) {
  if (!targetItem || !priceRow || targetItem.is_user) return false
  const norm = normalizeCode(String(priceRow.external_code || ''))
  targetItem.external_code = norm || null
  targetItem.note = priceRow.note ?? ''
  targetItem.description = null
  targetItem.unit = null
  targetItem.unit_price = null
  fitAllAutoHeightTextareas()
  return true
}

function clearPriceDragVisualState() {
  dropTargetItemId.value = null
  isListDropTarget.value = false
}

function handleCodeInputDragOver(event) {
  if (draggingPriceItem.value) {
    event.dataTransfer.dropEffect = 'copy'
  }
}

function handleCodeInputDrop(event, item) {
  const payload = getPriceItemPayloadForDrop(event)
  if (!payload) return
  applyPriceItemToTemplateItem(item, payload)
  clearPriceDragVisualState()
}

// 既存アイテムへのドラッグオーバー（行の dragleave は子要素間で誤発火するため使わない）
function handleItemDragOver(event, item) {
  if (draggingPriceItem.value) {
    event.dataTransfer.dropEffect = 'copy'
    if (!isListDropTarget.value) {
      isListDropTarget.value = true
    }
    return
  }
  if (draggingItemId.value && draggingItemId.value !== item.id) {
    if (itemDragOverId.value !== item.id) {
      itemDragOverId.value = item.id
    }
  }
}

/** セクション外へ出たときだけハイライト解除（子要素間の dragleave は無視） */
function handleTemplateSectionDragLeave(event) {
  const section = event.currentTarget
  const related = event.relatedTarget
  if (related && section.contains(related)) return
  isListDropTarget.value = false
  dropTargetItemId.value = null
  itemDragOverId.value = null
}

async function handleItemDrop(event, targetItem) {
  const pricePayload = getPriceItemPayloadForDrop(event)
  if (pricePayload) {
    addItemFromPriceList(pricePayload)
    clearPriceDragVisualState()
    return
  }

  // アイテム並び替え
  if (draggingItemId.value && draggingItemId.value !== targetItem.id) {
    const draggedIndex = templateItems.value.findIndex(i => i.id === draggingItemId.value)
    const targetIndex = templateItems.value.findIndex(i => i.id === targetItem.id)

    if (draggedIndex !== -1 && targetIndex !== -1) {
      const [removed] = templateItems.value.splice(draggedIndex, 1)
      const targetIndexAfterRemoval = templateItems.value.findIndex(i => i.id === targetItem.id)
      const insertIndex = draggedIndex < targetIndex ? targetIndexAfterRemoval + 1 : targetIndexAfterRemoval
      templateItems.value.splice(insertIndex, 0, removed)
    }
  }

  itemDragOverId.value = null
}

// リスト全体へのドラッグオーバー（行上は子の .stop で届かない＝行間・ヘッダー等のみ）
function handleListDragOver(event) {
  if (draggingPriceItem.value) {
    dropTargetItemId.value = null
    isListDropTarget.value = true
  }
}

async function handleListDrop(event) {
  if (draggingPriceItem.value && !dropTargetItemId.value) {
    addItemFromPriceList(draggingPriceItem.value)
  }
  isListDropTarget.value = false
}

// アイテム並び替えのドラッグ
function handleItemDragStart(event, item) {
  // プライスリストからのドラッグ中は無視
  if (draggingPriceItem.value) {
    event.preventDefault()
    return
  }
  draggingItemId.value = item.id
  event.dataTransfer.effectAllowed = isPersistedTemplateItem(item) ? 'copy' : 'move'
  event.dataTransfer.setData('text/plain', JSON.stringify({
    type: 'template-item',
    id: item.id,
    source_template_id: selectedTemplate.value?.id ?? null
  }))
}

function handleItemDragEnd() {
  draggingItemId.value = null
  itemDragOverId.value = null
  dropTargetItemId.value = null
  isListDropTarget.value = false
}

async function saveDetailPanel() {
  if (!selectedTemplate.value || !detailPanelBaseline.value) return
  if (!isDetailPanelDirty.value || detailPanelSaving.value) return

  if (shouldConfirmSaveForMaterialLabor(templateItems.value)) {
    const ok = await dialog.confirm(
      'A単価または労務単価が複数登録されていますが\n保存しますか？',
      { title: '確認' }
    )
    if (!ok) return
  }

  const templateId = selectedTemplate.value.id
  const base = detailPanelBaseline.value
  if (base.templateId !== templateId) return

  if (!(await assertServerItemsRevisionCurrent())) return

  detailPanelSaving.value = true
  try {
    const patch = {
      execution_detail: (implementationNote.value || '').trim() || null,
      industrial_waste: wasteDisposal.value || null,
      has_photo: !!hasPhoto.value,
      has_zumen: !!hasDrawing.value,
      has_evidence: !!hasPriceEvidence.value,
      has_etc: !!hasOther.value
    }
    const result = await supabaseService.saveBillingTemplateDetail(
      templateId,
      patch,
      getTemplateItemsSavePayload(),
      detailPanelServerItemsRevision.value ?? []
    )
    if (result?.template) {
      Object.assign(selectedTemplate.value, result.template)
      const listRow = templates.value.find((t) => t.id === templateId)
      if (listRow) Object.assign(listRow, result.template)
    } else {
      Object.assign(selectedTemplate.value, patch)
      const listRow = templates.value.find((t) => t.id === templateId)
      if (listRow) Object.assign(listRow, patch)
    }
    templateItems.value = (result?.items || []).map((item) => ({
      ...item,
      is_user: !!item.is_user,
      user_item: item.user_item ?? null,
      _isNew: false
    }))
    deletedPersistedItemIds.value = []
    setDetailPanelServerItemsRevision(templateItems.value)
    detailPanelBaseline.value = snapshotCurrentDetail()
  } catch (err) {
    console.error('saveDetailPanel:', err)
    const msg = String(err?.message || err)
    if (msg.includes('SERVER_ITEMS_CHANGED') || msg.includes('409')) {
      await handleServerItemsRevisionConflict()
      return
    }
    await dialog.alert('保存に失敗しました: ' + msg, { title: 'エラー' })
    deletedPersistedItemIds.value = []
    if (selectedTemplate.value) {
      const t = templates.value.find((x) => x.id === selectedTemplate.value.id)
      if (t) Object.assign(selectedTemplate.value, t)
      implementationNote.value = selectedTemplate.value.execution_detail || ''
      wasteDisposal.value = selectedTemplate.value.industrial_waste || ''
      hasPhoto.value = !!selectedTemplate.value.has_photo
      hasDrawing.value = !!selectedTemplate.value.has_zumen
      hasPriceEvidence.value = !!selectedTemplate.value.has_evidence
      hasOther.value = !!selectedTemplate.value.has_etc
      await loadTemplateItems()
    }
  } finally {
    detailPanelSaving.value = false
    fitAllAutoHeightTextareas()
  }
}

async function deleteTemplate(template) {
  if (template.label === 'temp') return
  const ok = await dialog.confirm(`「${template.label}」を削除しますか？`, { title: '確認' })
  if (!ok) return
  
  const index = templates.value.findIndex(t => t.id === template.id)
  const removed = templates.value.splice(index, 1)[0]
  
  if (selectedTemplate.value?.id === template.id) {
    selectedTemplate.value = null
    templateItems.value = []
    detailPanelBaseline.value = null
    deletedPersistedItemIds.value = []
  }
  
  try {
    await supabaseService.deleteBillingTemplate(template.id)
  } catch (err) {
    console.error('Failed to delete template:', err)
    templates.value.splice(index, 0, removed)
  }
}

