async function handleDropItemToTemplate(targetTemplate) {
  const itemId = draggingItemId.value
  if (!itemId || !selectedTemplate.value) return

  const sourceTemplateId = selectedTemplate.value.id
  if (sourceTemplateId === targetTemplate.id) return

  const item = templateItems.value.find((i) => i.id === itemId)
  if (!item) return

  if (!isPersistedTemplateItem(item)) {
    await dialog.alert(
      '未保存のアイテムは他のテンプレートに登録できません。\n先に保存してください。',
      { title: 'エラー' }
    )
    return
  }

  const confirmOptions = buildAppendItemConfirmOptions(targetTemplate, item)
  const confirmResult = await dialog.confirm(confirmOptions.message, confirmOptions)
  if (!confirmResult) return

  const userExternalCodeMode = confirmResult?.choice ?? undefined

  loading.value = true
  try {
    await supabaseService.appendBillingTemplateItemFromSource(targetTemplate.id, {
      source_item_id: itemId,
      source_template_id: sourceTemplateId,
      user_external_code_mode: userExternalCodeMode
    })
    await dialog.alert(
      `「${targetTemplate.label}」\nにアイテムを登録しました。`,
      { title: '成功' }
    )
  } catch (err) {
    console.error('handleDropItemToTemplate:', err)
    await dialog.alert(
      'アイテムの登録に失敗しました: ' + String(err?.message || err),
      { title: 'エラー' }
    )
  } finally {
    loading.value = false
  }
}

async function handleDrop(event, targetTemplate) {
  if (draggingItemId.value) {
    await handleDropItemToTemplate(targetTemplate)
    dragOverId.value = null
    return
  }

  if (targetTemplate.label === 'temp') {
    dragOverId.value = null
    return
  }
  
  const draggedId = draggingId.value
  if (!draggedId || draggedId === targetTemplate.id) {
    dragOverId.value = null
    return
  }
  
  const draggedIndex = templates.value.findIndex(t => t.id === draggedId)
  const targetIndex = templates.value.findIndex(t => t.id === targetTemplate.id)
  
  if (draggedIndex === -1 || targetIndex === -1) {
    dragOverId.value = null
    return
  }
  
  const [removed] = templates.value.splice(draggedIndex, 1)
  templates.value.splice(targetIndex, 0, removed)
  
  dragOverId.value = null
  await updateSortOrders()
}

async function updateSortOrders() {
  const updates = templates.value
    .filter(t => t.label !== 'temp')
    .map((t, i) => ({
      id: t.id,
      sort_order: i + 1
    }))
  
  let order = 0
  templates.value.forEach(t => {
    if (t.label === 'temp') {
      t.sort_order = 0
    } else {
      order++
      t.sort_order = order
    }
  })
  
  try {
    await supabaseService.reorderBillingTemplates(updates)
  } catch (err) {
    console.error('Failed to reorder templates:', err)
    await loadTemplates()
  }
}

function formatPrice(price) {
  if (price === null || price === undefined || price === '') return '0'
  const n = Number(price)
  if (!Number.isFinite(n)) return '0'
  return Math.floor(n).toLocaleString('ja-JP')
}

defineExpose({
  loadTemplates,
  loading
})
</script>

