import { processImageForUpload, isHeicLikeFile } from './imageResize'
import { resolveCameraPlaceholderUploadName } from './cameraCaptureUploadName.js'

/**
 * バックグラウンドアップロードキュー
 * 1件ずつリサイズとアップロードを処理し、他の操作を優先できるようにする
 */
class UploadQueue {
  constructor() {
    this.queue = []
    this.isProcessing = false
    this.isPaused = false
    this.pendingPriorityOperation = null
    this.onProgress = null
    this.currentIndex = 0
    this.totalCount = 0
    this.uploadBuffer = [] // アップロード用のバッファ（10件ずつ）
    this.UPLOAD_BATCH_SIZE = 10 // アップロードのバッチサイズ
    this.RESIZE_BATCH_SIZE = 10 // リサイズのバッチサイズ
    this.uploadResultsCallback = null // アップロード結果を返すコールバック
    this.queueChangeListeners = [] // キュー変更リスナー
    this.maxRetries = 3 // 最大リトライ回数
    this.retryDelay = 5000 // リトライ間隔（5秒）
    this.sessionSuccesses = []  // 今回の addFiles で成功した分（キュー完了時に success/errors へ反映）
    /** true のとき、errors があっても sessionSuccesses を success に載せる（部分コミット用） */
    this.allowPartialSessionResults = false
  }

  /**
   * キュー変更イベントをリッスン
   */
  onQueueChange(callback) {
    this.queueChangeListeners.push(callback)
    return () => {
      const index = this.queueChangeListeners.indexOf(callback)
      if (index > -1) {
        this.queueChangeListeners.splice(index, 1)
      }
    }
  }
  
  /**
   * キュー変更イベントを発火
   */
  emitQueueChange() {
    this.queueChangeListeners.forEach(callback => {
      try {
        callback()
      } catch (error) {
        console.error('Error in upload queue change listener:', error)
      }
    })
  }

  /**
   * ファイルをキューに追加
   * @param {Array<File>} files - アップロードするファイル
   * @param {string} workId - Work ID
   * @param {Object} uploadOptions - アップロードオプション
   * @param {Function} uploadSingleFileFn - 未使用（バッチアップロードを使用）
   * @param {Function} onProgress - 進行状況コールバック
   * @param {Object} uploadResultsCallback - アップロード結果を返すコールバック（{success: [], errors: []}）
   */
  async addFiles(files, workId, uploadOptions, uploadSingleFileFn, onProgress = null, uploadResultsCallback = null) {
    this.onProgress = onProgress
    this.uploadResultsCallback = uploadResultsCallback
    
    // 画像ファイル以外をフィルタリング
    // リサイズ可能な画像形式のみを許可
    const ALLOWED_IMAGE_EXTENSIONS = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp', 'heic', 'heif'];
    // リサイズできない画像形式を除外
    const DISALLOWED_IMAGE_EXTENSIONS = ['svg', 'ico', 'tiff', 'tif', 'avif', 'psd', 'ai', 'eps', 'raw', 'cr2', 'nef', 'orf', 'sr2'];
    
    const validFiles = [];
    const invalidFiles = [];
    
    for (const file of files) {
      // MIMEタイプでチェック
      if ((!file.type || !file.type.startsWith('image/')) && !isHeicLikeFile(file)) {
        invalidFiles.push(file.name);
        continue;
      }
      
      // 拡張子でチェック
      const fileName = file.name.toLowerCase();
      const ext = fileName.split('.').pop();
      
      // 拡張子がない場合は不許可
      if (!ext) {
        invalidFiles.push(file.name);
        continue;
      }
      
      // リサイズできない形式を除外
      if (DISALLOWED_IMAGE_EXTENSIONS.includes(ext)) {
        invalidFiles.push(file.name);
        continue;
      }
      
      // 許可された拡張子のみを許可
      if (!ALLOWED_IMAGE_EXTENSIONS.includes(ext)) {
        invalidFiles.push(file.name);
        continue;
      }
      
      validFiles.push(file);
    }

    if (invalidFiles.length > 0) {
      const errorMessage = `画像ファイル以外はアップロードできません: ${invalidFiles.join(', ')}`;
      console.warn('[UploadQueue] Invalid files rejected:', invalidFiles);
      if (this.uploadResultsCallback && this.uploadResultsCallback.errors) {
        for (const fileName of invalidFiles) {
          const file = files.find(f => f.name === fileName);
          if (file) {
            this.uploadResultsCallback.errors.push({
              file: file,
              error: errorMessage
            });
          }
        }
      }
      // 全体失敗: キューに追加せず、完了通知して終了
      if (this.onProgress) {
        this.onProgress({ active: false });
      }
      return;
    }
    
    if (validFiles.length === 0) {
      console.warn('[UploadQueue] No valid image files to upload');
      if (this.onProgress) {
        this.onProgress({ active: false });
      }
      return;
    }

    this.allowPartialSessionResults = !!uploadOptions.allowPartialUploadResult

    this.sessionSuccesses = []
    this.totalCount += validFiles.length

    // 各ファイルをキューに追加（validFilesのみ）
    for (const file of validFiles) {
      this.queue.push({
        file,
        workId,
        uploadOptions,
        retryCount: 0 // リトライカウントを追加
      })
    }

    // キュー変更イベントを発火
    this.emitQueueChange()

    // 処理を開始（既に処理中でない場合）
    if (!this.isProcessing && !this.isPaused) {
      this.processQueue()
    }
  }

  /**
   * キューを処理（1件ずつ）
   */
  async processQueue() {
    if (this.isProcessing || this.isPaused) {
      return
    }

    // オンライン状態チェック
    if (!navigator.onLine) {
      console.log('📴 [UploadQueue] Offline: Queue processing paused')
      return
    }

    // 優先操作が待機中の場合、処理を一時停止
    if (this.pendingPriorityOperation) {
      this.isPaused = true
      await this.pendingPriorityOperation()
      this.pendingPriorityOperation = null
      this.isPaused = false
    }

    if (this.queue.length === 0) {
      if (this.uploadBuffer.length > 0) {
        await this.uploadBatch()
      }
      this.isProcessing = false
      this.currentIndex = 0
      this.totalCount = 0
      this.uploadBuffer = []

      // 通常: errors が空のときだけ success に反映。allowPartialSessionResults 時は成功分を常に反映
      if (this.uploadResultsCallback) {
        const canPushSuccess =
          this.sessionSuccesses.length > 0 &&
          (this.allowPartialSessionResults || this.uploadResultsCallback.errors.length === 0)
        if (canPushSuccess) {
          this.uploadResultsCallback.success.push(...this.sessionSuccesses)
        }
        this.sessionSuccesses = []
      }
      this.allowPartialSessionResults = false

      if (this.onProgress) {
        this.onProgress({ active: false })
      }
      this.emitQueueChange()
      return
    }

    this.isProcessing = true

    // リサイズ用バッファに10件ずつ集める
    let resizeBatch = [] // let で宣言してcatchブロックからアクセス可能にする
    while (resizeBatch.length < this.RESIZE_BATCH_SIZE && this.queue.length > 0) {
      const item = this.queue.shift()
      resizeBatch.push(item)
    }

    try {
      // 1. リサイズ処理（画像の場合）- 10件ずつ並列処理
      const resizePromises = resizeBatch.map(async (item) => {
        let processedFile = item.file
        let thumbnail = null
        let sthumb = null
        let width = null
        let height = null
        let rotation = 0
        let exifDateTime = null
        let isStandardAspectRatio = false

        if ((item.file.type && item.file.type.startsWith('image/')) || isHeicLikeFile(item.file)) {
          try {
            const pre = item.uploadOptions?.boardCapturePreprocessed?.[item.file.name]
            if (pre?.mainImage && pre.thumbnail && pre.sthumb) {
              processedFile = pre.mainImage
              thumbnail = pre.thumbnail
              sthumb = pre.sthumb
              width = pre.width ?? null
              height = pre.height ?? null
              rotation = pre.rotation ?? 0
              exifDateTime = pre.exifDateTime ?? null
              isStandardAspectRatio = !!pre.isStandardAspectRatio
            } else {
              const result = await processImageForUpload(item.file)
              processedFile = result.mainImage
              thumbnail = result.thumbnail
              sthumb = result.sthumb
              width = result.width
              height = result.height
              rotation = result.rotation
              exifDateTime = result.exifDateTime
              isStandardAspectRatio = result.isStandardAspectRatio
            }
          } catch (error) {
            console.error(`[UploadQueue] 画像リサイズエラー (${item.file.name}):`, error)
            // リサイズできない形式の場合はエラーとして記録
            if (this.uploadResultsCallback && this.uploadResultsCallback.errors) {
              this.uploadResultsCallback.errors.push({
                file: item.file,
                error: error.message || '画像のリサイズに失敗しました'
              })
            }
            // エラーを再スローして、このファイルの処理をスキップ
            throw error
          }
        }

        return {
          workId: item.workId,
          processedFile,
          originalFile: item.file, // 元のファイルオブジェクトを保持（再送信用）
          originalFileName: resolveCameraPlaceholderUploadName(item.file.name, { outputExt: 'jpg' }),
          thumbnail,
          sthumb,
          uploadOptions: item.uploadOptions,
          retryCount: item.retryCount || 0, // リトライカウントを保持
          width,
          height,
          rotation,
          exifDateTime,
          isStandardAspectRatio
        }
      })

      // 10件並列でリサイズ処理（エラーが発生したファイルは除外）
      const resizeResults = []
      const resizePromisesWithErrorHandling = resizePromises.map(async (promise) => {
        try {
          return await promise
        } catch (error) {
          // エラーが発生したファイルは結果に含めない（エラーは既に記録済み）
          console.error('[UploadQueue] リサイズ処理でエラーが発生したファイルをスキップ:', error)
          return null
        }
      })
      
      const resizeResultsRaw = await Promise.all(resizePromisesWithErrorHandling)
      // null（エラーが発生したファイル）を除外
      for (const result of resizeResultsRaw) {
        if (result !== null) {
          resizeResults.push(result)
        }
      }

      // リサイズ完了後、進行状況を更新（リサイズ完了時点で更新）
      this.currentIndex += resizeResults.length
      if (this.onProgress) {
        this.onProgress({
          active: true,
          current: this.currentIndex,
          total: this.totalCount,
          fileName: resizeResults[resizeResults.length - 1]?.originalFileName || ''
        })
      }

      // リサイズ完了後、優先操作をチェック
      if (this.pendingPriorityOperation) {
        this.isPaused = true
        await this.pendingPriorityOperation()
        this.pendingPriorityOperation = null
        this.isPaused = false
      }

      // 2. アップロード用バッファに追加（10件ずつまとめてアップロード）
      for (const result of resizeResults) {
        this.uploadBuffer.push(result)
      }

      // バッファが10件になったら、またはキューが空になったらアップロード
      if (this.uploadBuffer.length >= this.UPLOAD_BATCH_SIZE || this.queue.length === 0) {
        try {
          await this.uploadBatch()
        } catch (uploadError) {
          console.error(`[UploadQueue] バッチアップロードエラー:`, uploadError)
          // バッチアップロードエラーが発生した場合、uploadBufferをクリア
          // （外側のcatchブロックでresizeBatchをキューに戻すため）
          this.uploadBuffer = []
          throw uploadError
        }
      }

    } catch (error) {
      console.error(`[UploadQueue] 処理エラー:`, error)
      
      // uploadBufferをクリア（エラーが発生したバッチは再試行）
      const failedBatch = this.uploadBuffer
      this.uploadBuffer = []
      
      // 失敗したバッチ（アップロード済みリサイズ結果）をリトライ処理
      if (failedBatch && failedBatch.length > 0) {
        for (const item of failedBatch) {
          // リトライカウントをインクリメント
          const retryCount = (item.retryCount || 0) + 1
          
          if (retryCount <= this.maxRetries) {
            // リトライ可能: キューの先頭に戻す（元のファイルを使用）
            console.warn(`⚠️ [UploadQueue] Retrying upload for file "${item.originalFileName}" (attempt ${retryCount}/${this.maxRetries})`)
            this.queue.unshift({
              file: item.originalFile,
              workId: item.workId,
              uploadOptions: item.uploadOptions,
              retryCount: retryCount
            })
          } else {
            // 最大リトライ回数に達した: エラーとして記録
            console.error(`💀 [UploadQueue] Upload failed permanently for file "${item.originalFileName}" after ${this.maxRetries} attempts`)
            if (this.uploadResultsCallback && this.uploadResultsCallback.errors) {
              this.uploadResultsCallback.errors.push({
                file: item.originalFile,
                error: `アップロードに失敗しました（${this.maxRetries}回試行）: ${error.message}`
              })
            }
          }
        }
      }
      
      // isProcessingをfalseに戻す
      this.isProcessing = false
      
      // リトライ可能なアイテムがある場合は、少し待ってから再試行
      const hasRetryableItems = this.queue.some(item => (item.retryCount || 0) > 0)
      if (hasRetryableItems) {
        console.log(`⏳ [UploadQueue] Waiting ${this.retryDelay}ms before retry...`)
        setTimeout(() => {
          this.processQueue()
        }, this.retryDelay)
      } else {
        // リトライ不要な場合は即座に次の処理を開始
        this.processQueue()
      }
      
      return // エラーを再スローしない（リトライ処理を行うため）
    }

    // 1件の処理が完了したので、isProcessingをfalseに戻す
    // 次のファイルを処理する前に、再帰呼び出しが正常に動作するようにする
    this.isProcessing = false

    this.processQueue()
  }

  /**
   * バッチアップロード（まとめて1つのリクエストでアップロード）
   */
  async uploadBatch() {
    if (this.uploadBuffer.length === 0) {
      return
    }

    const batch = [...this.uploadBuffer]
    this.uploadBuffer = []

    console.log(`📤 [UploadQueue] Starting batch upload: ${batch.length} files`)

    // 優先操作が待機中の場合、処理を一時停止
    if (this.pendingPriorityOperation) {
      this.isPaused = true
      await this.pendingPriorityOperation()
      this.pendingPriorityOperation = null
      this.isPaused = false
    }

    try {
      // バッチ内の最初のアイテムの情報を使用（workIdとuploadOptionsは同じはず）
      const firstItem = batch[0]
      const workId = firstItem.workId
      const uploadOptions = firstItem.uploadOptions

      // supabaseServiceをインポート（動的インポート）
      const { supabaseService } = await import('../services/supabase.js')

      // 1つのリクエストでまとめてアップロード
      const uploadedFiles = await supabaseService.uploadBatchFiles(workId, batch, uploadOptions)
      
      console.log(`✅ [UploadQueue] Batch upload successful: ${uploadedFiles.length}/${batch.length} files`)
      
      // アップロード完了後、キュー変更イベントを発火
      this.emitQueueChange()
      
      // アップロード成功分を一時保持（キュー完了時に errors がなければ success へ反映）
      if (uploadedFiles && uploadedFiles.length > 0) {
        this.sessionSuccesses.push(...uploadedFiles)
      }
      
      // 部分的な失敗をチェック（成功件数 < 送信件数）
      if (uploadedFiles.length < batch.length) {
        console.warn(`⚠️ [UploadQueue] Partial failure: ${batch.length - uploadedFiles.length} files failed`)
        
        // 失敗したファイルを特定してリトライ
        const uploadedFileNames = new Set(uploadedFiles.map(f => f.original_name))
        const failedItems = batch.filter(item => !uploadedFileNames.has(item.originalFileName))
        
        console.log(`Failed files: ${failedItems.map(f => f.originalFileName).join(', ')}`)
        
        // 失敗したファイルのみをリトライ処理
        for (const item of failedItems) {
          const retryCount = (item.retryCount || 0) + 1
          
          if (retryCount <= this.maxRetries) {
            console.warn(`⚠️ [UploadQueue] Retrying failed file "${item.originalFileName}" (attempt ${retryCount}/${this.maxRetries})`)
            this.queue.unshift({
              file: item.originalFile,
              workId: item.workId,
              uploadOptions: item.uploadOptions,
              retryCount: retryCount
            })
          } else {
            console.error(`💀 [UploadQueue] Upload failed permanently for file "${item.originalFileName}" after ${this.maxRetries} attempts`)
            if (this.uploadResultsCallback && this.uploadResultsCallback.errors) {
              this.uploadResultsCallback.errors.push({
                file: item.originalFile,
                error: `アップロードに失敗しました（${this.maxRetries}回試行）`
              })
            }
          }
        }
      }
      
      return uploadedFiles
    } catch (error) {
      console.error(`❌ [UploadQueue] uploadBatch: Batch upload error:`, error)

      // キュー変更イベントを発火
      this.emitQueueChange()

      // エラーは呼び出し元（processQueue）で処理される
      // リトライ処理がある場合は、ここでエラーを記録しない
      throw error
    }

    // アップロード完了後、優先操作をチェック
    if (this.pendingPriorityOperation) {
      this.isPaused = true
      await this.pendingPriorityOperation()
      this.pendingPriorityOperation = null
      this.isPaused = false
    }
  }

  /**
   * 優先操作を実行（1件の処理完了後に実行）
   * @param {Function} operation - 実行する操作
   */
  async executePriorityOperation(operation) {
    if (this.isProcessing) {
      // 処理中の場合、次のチェックポイントで実行
      this.pendingPriorityOperation = operation
    } else {
      // 処理中でない場合、即座に実行
      await operation()
    }
  }

  /**
   * キューをクリア
   */
  clear() {
    this.queue = []
    this.isProcessing = false
    this.isPaused = false
    this.pendingPriorityOperation = null
    this.currentIndex = 0
    this.totalCount = 0
    this.uploadBuffer = []
    this.sessionSuccesses = []
    this.allowPartialSessionResults = false
    if (this.onProgress) {
      this.onProgress({ active: false })
    }
    // キュー変更イベントを発火
    this.emitQueueChange()
  }

  /**
   * キューが空かどうか
   */
  isEmpty() {
    return this.queue.length === 0 && !this.isProcessing
  }

  /**
   * 処理中かどうか
   */
  getProcessing() {
    return this.isProcessing || this.isPaused
  }

  /**
   * 未アップロード数を取得
   * @returns {number} 未アップロード数
   */
  getPendingCount() {
    // キューに残っているファイル + アップロードバッファのファイル = まだアップロードされていないファイル
    // totalCount - currentIndex でも計算可能だが、より明示的にする
    const pendingCount = this.queue.length + this.uploadBuffer.length
    return pendingCount
  }
}

// シングルトンインスタンス
export const uploadQueue = new UploadQueue()

// オンライン/オフライン状態の監視
window.addEventListener('online', () => {
  console.log('🌐 [UploadQueue] Back online: Processing upload queue')
  uploadQueue.processQueue()
})

window.addEventListener('offline', () => {
  console.log('📴 [UploadQueue] Went offline: Upload queue processing paused')
})

