<template>
  <div class="exclusion-code-editor">
    <div class="editor-header">
      <div class="header-content">
        <button
          class="save-btn"
          @click="saveItems"
          :disabled="saving || !isDirty"
        >
          {{ saving ? '保存中...' : '保存' }}
        </button>
        <h3>除外コード</h3>
      </div>
      <p class="editor-description">
        類似取得の候補から除外する単価コードを登録します（ユーザー単位）
      </p>
      <span v-if="isDirty" class="dirty-indicator">※ 未保存の変更があります</span>
    </div>

    <div v-if="loading" class="loading-state">読み込み中...</div>

    <div v-else class="items-form">
      <div class="items-header">
        <span class="col-code">単価コード</span>
        <span class="col-summary">概要</span>
        <span class="col-action"></span>
      </div>
      <div
        v-for="(row, index) in rows"
        :key="row._key"
        class="item-row"
      >
        <input
          v-model="row.external_code"
          type="text"
          class="code-input"
          placeholder="単価コード"
          @input="markDirty"
        />
        <input
          v-model="row.summary"
          type="text"
          class="summary-input"
          placeholder="概要（任意）"
          @input="markDirty"
        />
        <button
          type="button"
          class="delete-btn"
          title="行を削除"
          @click="removeRow(index)"
        >
          ✕
        </button>
      </div>
      <button type="button" class="add-btn" @click="addRow">＋ 行を追加</button>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { supabaseService } from '../services/supabase'
import { useDialog } from '../composables/useDialog'

const loading = ref(false)
const saving = ref(false)
const isDirty = ref(false)
const rows = ref([])
const dialog = useDialog()

let nextRowKey = 1

function makeRow(item = {}) {
  return {
    _key: nextRowKey++,
    external_code: item.external_code ?? '',
    summary: item.summary ?? ''
  }
}

function markDirty() {
  isDirty.value = true
}

function addRow() {
  rows.value.push(makeRow())
  markDirty()
}

function removeRow(index) {
  rows.value.splice(index, 1)
  markDirty()
}

async function loadItems() {
  loading.value = true
  try {
    const result = await supabaseService.getExclusionCodes()
    const items = Array.isArray(result?.items) ? result.items : []
    rows.value = items.map((item) => makeRow(item))
    if (rows.value.length === 0) {
      rows.value.push(makeRow())
    }
    isDirty.value = false
  } catch (err) {
    console.error('Failed to load exclusion codes:', err)
    await dialog.alert('除外コードの読み込みに失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    loading.value = false
  }
}

async function saveItems() {
  saving.value = true
  try {
    const payload = rows.value
      .map((row) => ({
        external_code: String(row.external_code ?? '').trim(),
        summary: String(row.summary ?? '').trim()
      }))
      .filter((row) => row.external_code !== '')

    await supabaseService.saveExclusionCodes(payload)
    await loadItems()
  } catch (err) {
    console.error('Failed to save exclusion codes:', err)
    await dialog.alert('保存に失敗しました: ' + err.message, { title: 'エラー' })
  } finally {
    saving.value = false
  }
}

function reload() {
  loadItems()
}

onMounted(() => {
  loadItems()
})

defineExpose({
  loading,
  reload
})
</script>

<style scoped>
.exclusion-code-editor {
  padding: 20px;
  max-width: 720px;
}

.editor-header {
  margin-bottom: 20px;
}

.header-content {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
}

.editor-header h3 {
  margin: 0;
  font-size: 18px;
  color: #1f2937;
}

.editor-description {
  margin: 0 0 4px 0;
  font-size: 13px;
  color: #6b7280;
}

.loading-state {
  padding: 20px;
  text-align: center;
  color: #6b7280;
}

.items-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.items-header {
  display: grid;
  grid-template-columns: 160px 1fr 36px;
  gap: 8px;
  font-size: 12px;
  font-weight: 600;
  color: #6b7280;
  padding: 0 4px;
}

.item-row {
  display: grid;
  grid-template-columns: 160px 1fr 36px;
  gap: 8px;
  align-items: center;
}

.code-input,
.summary-input {
  padding: 8px 12px;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  font-size: 14px;
}

.code-input:focus,
.summary-input:focus {
  outline: none;
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.delete-btn {
  width: 32px;
  height: 32px;
  border: 1px solid #e5e7eb;
  border-radius: 4px;
  background: #fff;
  color: #6b7280;
  cursor: pointer;
}

.delete-btn:hover {
  background: #fef2f2;
  color: #dc2626;
  border-color: #fecaca;
}

.add-btn {
  align-self: flex-start;
  margin-top: 8px;
  padding: 8px 14px;
  border: 1px dashed #93c5fd;
  border-radius: 4px;
  background: #eff6ff;
  color: #2563eb;
  font-size: 13px;
  cursor: pointer;
}

.add-btn:hover {
  background: #dbeafe;
}

.save-btn {
  padding: 8px 20px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 4px;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.2s;
}

.save-btn:hover:not(:disabled) {
  background: #2563eb;
}

.save-btn:disabled {
  background: #9ca3af;
  cursor: not-allowed;
}

.dirty-indicator {
  font-size: 12px;
  color: #f59e0b;
}
</style>
